def __iter__(self):
    if self.field.empty_label is not None:
        yield ("", self.field.empty_label)
    queryset = self.queryset
    # Can't use iterator() when queryset uses prefetch_related()
    if not queryset._prefetch_related_lookups:
        queryset = queryset.iterator()
    for obj in queryset:
        yield self.choice(obj)

def choice(self, obj):
    return (
        ModelChoiceIteratorValue(self.field.prepare_value(obj), obj),
        self.field.label_from_instance(obj),
    )

def default(self, obj):
    if isinstance(obj, Message):
        # Using 0/1 here instead of False/True to produce more compact json
        is_safedata = 1 if isinstance(obj.message, SafeData) else 0
        message = [self.message_key, is_safedata, obj.level, obj.message]
        if obj.extra_tags:
            message.append(obj.extra_tags)
        return message
    return super().default(obj)

def decode(self, s, **kwargs):
    decoded = super().decode(s, **kwargs)
    return self.process_messages(decoded)

def process_messages(self, obj):
    if isinstance(obj, list) and obj:
        if obj[0] == MessageEncoder.message_key:
            if obj[1]:
                obj[3] = mark_safe(obj[3])
            return Message(*obj[2:])
        return [self.process_messages(item) for item in obj]
    if isinstance(obj, dict):
        return {key: self.process_messages(value)
                for key, value in obj.items()}
    return obj

def __eq__(self, other):
    if not isinstance(other, Message):
        return NotImplemented
    return self.level == other.level and self.message == other.message

def dumps(self, obj):
    return json.dumps(
        obj,
        separators=(',', ':'),
        cls=MessageEncoder,
    ).encode('latin-1')

def __new__(metacls, classname, bases, classdict, **kwds):
    labels = []
    for key in classdict._member_names:
        value = classdict[key]
        if (
            isinstance(value, (list, tuple))
            and len(value) > 1
            and isinstance(value[-1], (Promise, str))
        ):
            *value, label = value
            value = tuple(value)
        else:
            label = key.replace("_", " ").title()
        labels.append(label)
        # Use dict.__setitem__() to suppress defenses against double
        # assignment in enum's classdict.
        dict.__setitem__(classdict, key, value)
    cls = super().__new__(metacls, classname, bases, classdict, **kwds)
    for member, label in zip(cls.__members__.values(), labels):
        member._label_ = label
    return enum.unique(cls)

def serialize(self):
    enum_class = self.value.__class__
    module = enum_class.__module__
    return (
        "%s.%s[%r]" % (module, enum_class.__qualname__, self.value.name),
        {"import %s" % module},
    )

def serializer_factory(value):
    if isinstance(value, Promise):
        value = str(value)
    elif isinstance(value, LazyObject):
        # The unwrapped value is returned as the first item of the arguments
        # tuple.
        value = value.__reduce__()[1][0]

    if isinstance(value, models.Field):
        return ModelFieldSerializer(value)
    if isinstance(value, models.manager.BaseManager):
        return ModelManagerSerializer(value)
    if isinstance(value, Operation):
        return OperationSerializer(value)
    if isinstance(value, type):
        return TypeSerializer(value)
    # Anything that knows how to deconstruct itself.
    if hasattr(value, "deconstruct"):
        return DeconstructableSerializer(value)
    for type_, serializer_cls in Serializer._registry.items():
        if isinstance(value, type_):
            return serializer_cls(value)
    raise ValueError(
        "Cannot serialize: %r\nThere are some values Django cannot serialize into "
        "migration files.\nFor more, see https://docs.djangoproject.com/en/%s/"
        "topics/migrations/#migration-serializing" % (value, get_docs_version())
    )

def serialize(self):
    raise NotImplementedError(
        "Subclasses of BaseSerializer must implement the serialize() method."
    )

def submit_row_tag(parser, token):
    return InclusionAdminNode(
        parser, token, func=submit_row, template_name="submit_line.html"
    )

def change_form_object_tools_tag(parser, token):
    """Display the row of change form object tools."""
    return InclusionAdminNode(
        parser,
        token,
        func=lambda context: context,
        template_name="change_form_object_tools.html",
    )

def cell_count(inline_admin_form):
    """Return the number of cells used in a tabular inline."""
    count = 1  # Hidden cell with hidden 'id' field
    for fieldset in inline_admin_form:
        # Count all visible fields.
        for line in fieldset:
            for field in line:
                try:
                    is_hidden = field.field.is_hidden
                except AttributeError:
                    is_hidden = field.field["is_hidden"]
                if not is_hidden:
                    count += 1
    if inline_admin_form.formset.can_delete:
        # Delete checkbox
        count += 1
    return count

def changeform_view(self, request, object_id=None, form_url="", extra_context=None):
    with transaction.atomic(using=router.db_for_write(self.model)):
        return self._changeform_view(request, object_id, form_url, extra_context)

def _changeform_view(self, request, object_id, form_url, extra_context):
    to_field = request.POST.get(TO_FIELD_VAR, request.GET.get(TO_FIELD_VAR))
    if to_field and not self.to_field_allowed(request, to_field):
        raise DisallowedModelAdminToField(
            "The field %s cannot be referenced." % to_field
        )

    if request.method == "POST" and "_saveasnew" in request.POST:
        object_id = None

    add = object_id is None

    if add:
        if not self.has_add_permission(request):
            raise PermissionDenied
        obj = None

    else:
        obj = self.get_object(request, unquote(object_id), to_field)

        if request.method == "POST":
            if not self.has_change_permission(request, obj):
                raise PermissionDenied
        else:
            if not self.has_view_or_change_permission(request, obj):
                raise PermissionDenied

        if obj is None:
            return self._get_obj_does_not_exist_redirect(
                request, self.opts, object_id
            )

    fieldsets = self.get_fieldsets(request, obj)
    ModelForm = self.get_form(
        request, obj, change=not add, fields=flatten_fieldsets(fieldsets)
    )
    if request.method == "POST":
        form = ModelForm(request.POST, request.FILES, instance=obj)
        formsets, inline_instances = self._create_formsets(
            request,
            form.instance,
            change=not add,
        )
        form_validated = form.is_valid()
        if form_validated:
            new_object = self.save_form(request, form, change=not add)
        else:
            new_object = form.instance
        if all_valid(formsets) and form_validated:
            self.save_model(request, new_object, form, not add)
            self.save_related(request, form, formsets, not add)
            change_message = self.construct_change_message(
                request, form, formsets, add
            )
            if add:
                self.log_addition(request, new_object, change_message)
                return self.response_add(request, new_object)
            else:
                self.log_change(request, new_object, change_message)
                return self.response_change(request, new_object)
        else:
            form_validated = False
    else:
        if add:
            initial = self.get_changeform_initial_data(request)
            form = ModelForm(initial=initial)
            formsets, inline_instances = self._create_formsets(
                request, form.instance, change=False
            )
        else:
            form = ModelForm(instance=obj)
            formsets, inline_instances = self._create_formsets(
                request, obj, change=True
            )

    if not add and not self.has_change_permission(request, obj):
        readonly_fields = flatten_fieldsets(fieldsets)
    else:
        readonly_fields = self.get_readonly_fields(request, obj)
    admin_form = helpers.AdminForm(
        form,
        list(fieldsets),
        # Clear prepopulated fields on a view-only form to avoid a crash.
        self.get_prepopulated_fields(request, obj)
        if add or self.has_change_permission(request, obj)
        else {},
        readonly_fields,
        model_admin=self,
    )
    media = self.media + admin_form.media

    inline_formsets = self.get_inline_formsets(
        request, formsets, inline_instances, obj
    )
    for inline_formset in inline_formsets:
        media += inline_formset.media

    if add:
        title = _("Add %s")
    elif self.has_change_permission(request, obj):
        title = _("Change %s")
    else:
        title = _("View %s")
    context = {
        **self.admin_site.each_context(request),
        "title": title % self.opts.verbose_name,
        "subtitle": str(obj) if obj else None,
        "adminform": admin_form,
        "object_id": object_id,
        "original": obj,
        "is_popup": IS_POPUP_VAR in request.POST or IS_POPUP_VAR in request.GET,
        "to_field": to_field,
        "media": media,
        "inline_admin_formsets": inline_formsets,
        "errors": helpers.AdminErrorList(form, formsets),
        "preserved_filters": self.get_preserved_filters(request),
    }

    # Hide the "Save" and "Save and continue" buttons if "Save as New" was
    # previously chosen to prevent the interface from getting confusing.
    if (
        request.method == "POST"
        and not form_validated
        and "_saveasnew" in request.POST
    ):
        context["show_save"] = False
        context["show_save_and_continue"] = False
        # Use the change template instead of the add template.
        add = False

    context.update(extra_context or {})

    return self.render_change_form(
        request, context, add=add, change=not add, obj=obj, form_url=form_url
    )

def prepopulated_fields_js(context):
    """
    Create a list of prepopulated_fields that should render JavaScript for
    the prepopulated fields for both the admin form and inlines.
    """
    prepopulated_fields = []
    if "adminform" in context:
        prepopulated_fields.extend(context["adminform"].prepopulated_fields)
    if "inline_admin_formsets" in context:
        for inline_admin_formset in context["inline_admin_formsets"]:
            for inline_admin_form in inline_admin_formset:
                if inline_admin_form.original is None:
                    prepopulated_fields.extend(inline_admin_form.prepopulated_fields)

    prepopulated_fields_json = []
    for field in prepopulated_fields:
        prepopulated_fields_json.append(
            {
                "id": "#%s" % field["field"].auto_id,
                "name": field["field"].name,
                "dependency_ids": [
                    "#%s" % dependency.auto_id for dependency in field["dependencies"]
                ],
                "dependency_list": [
                    dependency.name for dependency in field["dependencies"]
                ],
                "maxLength": field["field"].field.max_length or 50,
                "allowUnicode": getattr(field["field"].field, "allow_unicode", False),
            }
        )

    context.update(
        {
            "prepopulated_fields": prepopulated_fields,
            "prepopulated_fields_json": json.dumps(prepopulated_fields_json),
        }
    )
    return context

def prepopulated_fields_js_tag(parser, token):
    return InclusionAdminNode(
        parser,
        token,
        func=prepopulated_fields_js,
        template_name="prepopulated_fields_js.html",
    )

def get_rotation(rotation):
    """
    Return *rotation* normalized to an angle between 0 and 360 degrees.

    Parameters
    ----------
    rotation : float or {None, 'horizontal', 'vertical'}
        Rotation angle in degrees. *None* and 'horizontal' equal 0,
        'vertical' equals 90.

    Returns
    -------
    float
    """
    try:
        return float(rotation) % 360
    except (ValueError, TypeError) as err:
        if cbook._str_equal(rotation, 'horizontal') or rotation is None:
            return 0.
        elif cbook._str_equal(rotation, 'vertical'):
            return 90.
        else:
            raise ValueError("rotation is {!r}; expected either 'horizontal', "
                             "'vertical', numeric value, or None"
                             .format(rotation)) from err

def _set_tick_locations(self, ticks, *, minor=False):
    # see docstring of set_ticks

    # XXX if the user changes units, the information will be lost here
    ticks = self.convert_units(ticks)
    for name, axis in self.axes._axis_map.items():
        if self is axis:
            shared = [
                getattr(ax, f"{name}axis")
                for ax
                in self.axes._shared_axes[name].get_siblings(self.axes)]
            break
    else:
        shared = [self]
    if len(ticks):
        for axis in shared:
            # set_view_interval maintains any preexisting inversion.
            axis.set_view_interval(min(ticks), max(ticks))
    self.axes.stale = True
    if minor:
        self.set_minor_locator(mticker.FixedLocator(ticks))
        return self.get_minor_ticks(len(ticks))
    else:
        self.set_major_locator(mticker.FixedLocator(ticks))
        return self.get_major_ticks(len(ticks))

def _compute_stats(self, spec: Plot, layers: list[Layer]) -> None:

    grouping_vars = [v for v in PROPERTIES if v not in "xy"]
    grouping_vars += ["col", "row", "group"]

    pair_vars = spec._pair_spec.get("structure", {})

    for layer in layers:

        data = layer["data"]
        mark = layer["mark"]
        stat = layer["stat"]

        if stat is None:
            continue

        iter_axes = itertools.product(*[
            pair_vars.get(axis, [axis]) for axis in "xy"
        ])

        old = data.frame

        if pair_vars:
            data.frames = {}
            data.frame = data.frame.iloc[:0]  # TODO to simplify typing

        for coord_vars in iter_axes:

            pairings = "xy", coord_vars

            df = old.copy()
            scales = self._scales.copy()

            for axis, var in zip(*pairings):
                if axis != var:
                    df = df.rename(columns={var: axis})
                    drop_cols = [x for x in df if re.match(rf"{axis}\d+", x)]
                    df = df.drop(drop_cols, axis=1)
                    scales[axis] = scales[var]

            orient = layer["orient"] or mark._infer_orient(scales)

            if stat.group_by_orient:
                grouper = [orient, *grouping_vars]
            else:
                grouper = grouping_vars
            groupby = GroupBy(grouper)
            res = stat(df, groupby, orient, scales)

            if pair_vars:
                data.frames[coord_vars] = res
            else:
                data.frame = res

def apply(
    self, data: DataFrame, func: Callable[..., DataFrame],
    *args, **kwargs,
) -> DataFrame:
    """Apply a DataFrame -> DataFrame mapping to each group."""
    grouper, groups = self._get_groups(data)

    if not grouper:
        return self._reorder_columns(func(data, *args, **kwargs), data)

    parts = {}
    for key, part_df in data.groupby(grouper, sort=False):
        parts[key] = func(part_df, *args, **kwargs)
    stack = []
    for key in groups:
        if key in parts:
            if isinstance(grouper, list):
                group_ids = dict(zip(grouper, key))
            else:
                group_ids = {grouper: key}
            stack.append(parts[key].assign(**group_ids))

    res = pd.concat(stack, ignore_index=True)
    return self._reorder_columns(res, data)

def _fit_predict(self, data):

    x = data["x"]
    y = data["y"]
    if x.nunique() <= self.order:
        # TODO warn?
        xx = yy = []
    else:
        p = np.polyfit(x, y, self.order)
        xx = np.linspace(x.min(), x.max(), self.gridsize)
        yy = np.polyval(p, xx)

    return pd.DataFrame(dict(x=xx, y=yy))

def add_url_rule(
    self,
    rule: str,
    endpoint: t.Optional[str] = None,
    view_func: t.Optional[ft.RouteCallable] = None,
    provide_automatic_options: t.Optional[bool] = None,
    **options: t.Any,
) -> None:
    if endpoint is None:
        endpoint = _endpoint_from_view_func(view_func)  # type: ignore
    options["endpoint"] = endpoint
    methods = options.pop("methods", None)

    # if the methods are not given and the view_func object knows its
    # methods we can use that instead.  If neither exists, we go with
    # a tuple of only ``GET`` as default.
    if methods is None:
        methods = getattr(view_func, "methods", None) or ("GET",)
    if isinstance(methods, str):
        raise TypeError(
            "Allowed methods must be a list of strings, for"
            ' example: @app.route(..., methods=["POST"])'
        )
    methods = {item.upper() for item in methods}

    # Methods that should always be added
    required_methods = set(getattr(view_func, "required_methods", ()))

    # starting with Flask 0.8 the view_func object can disable and
    # force-enable the automatic options handling.
    if provide_automatic_options is None:
        provide_automatic_options = getattr(
            view_func, "provide_automatic_options", None
        )

    if provide_automatic_options is None:
        if "OPTIONS" not in methods:
            provide_automatic_options = True
            required_methods.add("OPTIONS")
        else:
            provide_automatic_options = False

    # Add the required methods now.
    methods |= required_methods

    rule = self.url_rule_class(rule, methods=methods, **options)
    rule.provide_automatic_options = provide_automatic_options  # type: ignore

    self.url_map.add(rule)
    if view_func is not None:
        old_func = self.view_functions.get(endpoint)
        if old_func is not None and old_func != view_func:
            raise AssertionError(
                "View function mapping is overwriting an existing"
                f" endpoint function: {endpoint}"
            )
        self.view_functions[endpoint] = view_func

def iter_blueprints(self) -> t.ValuesView["Blueprint"]:
    """Iterates over all blueprints by the order they were registered.

    .. versionadded:: 0.11
    """
    return self.blueprints.values()

def _dataset_concat(
    datasets,
    dim,
    data_vars,
    coords,
    compat,
    positions,
    fill_value=dtypes.NA,
    join="outer",
):
    """
    Concatenate a sequence of datasets along a new or existing dimension
    """
    from .dataset import Dataset

    dim, coord = _calc_concat_dim_coord(dim)
    # Make sure we're working on a copy (we'll be loading variables)
    datasets = [ds.copy() for ds in datasets]
    datasets = align(
        *datasets, join=join, copy=False, exclude=[dim], fill_value=fill_value
    )

    dim_coords, dims_sizes, coord_names, data_names = _parse_datasets(datasets)
    dim_names = set(dim_coords)
    unlabeled_dims = dim_names - coord_names

    both_data_and_coords = coord_names & data_names
    if both_data_and_coords:
        raise ValueError(
            "%r is a coordinate in some datasets but not others." % both_data_and_coords
        )
    # we don't want the concat dimension in the result dataset yet
    dim_coords.pop(dim, None)
    dims_sizes.pop(dim, None)

    # case where concat dimension is a coordinate or data_var but not a dimension
    if (dim in coord_names or dim in data_names) and dim not in dim_names:
        datasets = [ds.expand_dims(dim) for ds in datasets]

    # determine which variables to concatentate
    concat_over, equals, concat_dim_lengths = _calc_concat_over(
        datasets, dim, dim_names, data_vars, coords, compat
    )

    # determine which variables to merge, and then merge them according to compat
    variables_to_merge = (coord_names | data_names) - concat_over - dim_names

    result_vars = {}
    if variables_to_merge:
        to_merge = {var: [] for var in variables_to_merge}

        for ds in datasets:
            absent_merge_vars = variables_to_merge - set(ds.variables)
            if absent_merge_vars:
                raise ValueError(
                    "variables %r are present in some datasets but not others. "
                    % absent_merge_vars
                )

            for var in variables_to_merge:
                to_merge[var].append(ds.variables[var])

        for var in variables_to_merge:
            result_vars[var] = unique_variable(
                var, to_merge[var], compat=compat, equals=equals.get(var, None)
            )
    else:
        result_vars = {}
    result_vars.update(dim_coords)

    # assign attrs and encoding from first dataset
    result_attrs = datasets[0].attrs
    result_encoding = datasets[0].encoding

    # check that global attributes are fixed across all datasets if necessary
    for ds in datasets[1:]:
        if compat == "identical" and not utils.dict_equiv(ds.attrs, result_attrs):
            raise ValueError("Dataset global attributes not equal.")

    # we've already verified everything is consistent; now, calculate
    # shared dimension sizes so we can expand the necessary variables
    def ensure_common_dims(vars):
        # ensure each variable with the given name shares the same
        # dimensions and the same shape for all of them except along the
        # concat dimension
        common_dims = tuple(pd.unique([d for v in vars for d in v.dims]))
        if dim not in common_dims:
            common_dims = (dim,) + common_dims
        for var, dim_len in zip(vars, concat_dim_lengths):
            if var.dims != common_dims:
                common_shape = tuple(dims_sizes.get(d, dim_len) for d in common_dims)
                var = var.set_dims(common_dims, common_shape)
            yield var

    # stack up each variable to fill-out the dataset (in order)
    # n.b. this loop preserves variable order, needed for groupby.
    for k in datasets[0].variables:
        if k in concat_over:
            try:
                vars = ensure_common_dims([ds.variables[k] for ds in datasets])
            except KeyError:
                raise ValueError("%r is not present in all datasets." % k)
            combined = concat_vars(vars, dim, positions)
            assert isinstance(combined, Variable)
            result_vars[k] = combined

    result = Dataset(result_vars, attrs=result_attrs)
    absent_coord_names = coord_names - set(result.variables)
    if absent_coord_names:
        raise ValueError(
            "Variables %r are coordinates in some datasets but not others."
            % absent_coord_names
        )
    result = result.set_coords(coord_names)
    result.encoding = result_encoding

    result = result.drop(unlabeled_dims, errors="ignore")

    if coord is not None:
        # add concat dimension last to ensure that its in the final Dataset
        result[coord.name] = coord

    return result

def _calc_concat_over(datasets, dim, dim_names, data_vars, coords, compat):
    """
    Determine which dataset variables need to be concatenated in the result,
    """
    # Return values
    concat_over = set()
    equals = {}

    if dim in dim_names:
        concat_over_existing_dim = True
        concat_over.add(dim)
    else:
        concat_over_existing_dim = False

    concat_dim_lengths = []
    for ds in datasets:
        if concat_over_existing_dim:
            if dim not in ds.dims:
                if dim in ds:
                    ds = ds.set_coords(dim)
        concat_over.update(k for k, v in ds.variables.items() if dim in v.dims)
        concat_dim_lengths.append(ds.dims.get(dim, 1))

    def process_subset_opt(opt, subset):
        if isinstance(opt, str):
            if opt == "different":
                if compat == "override":
                    raise ValueError(
                        "Cannot specify both %s='different' and compat='override'."
                        % subset
                    )
                # all nonindexes that are not the same in each dataset
                for k in getattr(datasets[0], subset):
                    if k not in concat_over:
                        # Compare the variable of all datasets vs. the one
                        # of the first dataset. Perform the minimum amount of
                        # loads in order to avoid multiple loads from disk
                        # while keeping the RAM footprint low.
                        v_lhs = datasets[0].variables[k].load()
                        # We'll need to know later on if variables are equal.
                        computed = []
                        for ds_rhs in datasets[1:]:
                            v_rhs = ds_rhs.variables[k].compute()
                            computed.append(v_rhs)
                            if not getattr(v_lhs, compat)(v_rhs):
                                concat_over.add(k)
                                equals[k] = False
                                # computed variables are not to be re-computed
                                # again in the future
                                for ds, v in zip(datasets[1:], computed):
                                    ds.variables[k].data = v.data
                                break
                        else:
                            equals[k] = True

            elif opt == "all":
                concat_over.update(
                    set(getattr(datasets[0], subset)) - set(datasets[0].dims)
                )
            elif opt == "minimal":
                pass
            else:
                raise ValueError("unexpected value for %s: %s" % (subset, opt))
        else:
            invalid_vars = [k for k in opt if k not in getattr(datasets[0], subset)]
            if invalid_vars:
                if subset == "coords":
                    raise ValueError(
                        "some variables in coords are not coordinates on "
                        "the first dataset: %s" % (invalid_vars,)
                    )
                else:
                    raise ValueError(
                        "some variables in data_vars are not data variables "
                        "on the first dataset: %s" % (invalid_vars,)
                    )
            concat_over.update(opt)

    process_subset_opt(data_vars, "data_vars")
    process_subset_opt(coords, "coords")
    return concat_over, equals, concat_dim_lengths

def process_subset_opt(opt, subset):
    if isinstance(opt, str):
        if opt == "different":
            if compat == "override":
                raise ValueError(
                    "Cannot specify both %s='different' and compat='override'."
                    % subset
                )
            # all nonindexes that are not the same in each dataset
            for k in getattr(datasets[0], subset):
                if k not in concat_over:
                    # Compare the variable of all datasets vs. the one
                    # of the first dataset. Perform the minimum amount of
                    # loads in order to avoid multiple loads from disk
                    # while keeping the RAM footprint low.
                    v_lhs = datasets[0].variables[k].load()
                    # We'll need to know later on if variables are equal.
                    computed = []
                    for ds_rhs in datasets[1:]:
                        v_rhs = ds_rhs.variables[k].compute()
                        computed.append(v_rhs)
                        if not getattr(v_lhs, compat)(v_rhs):
                            concat_over.add(k)
                            equals[k] = False
                            # computed variables are not to be re-computed
                            # again in the future
                            for ds, v in zip(datasets[1:], computed):
                                ds.variables[k].data = v.data
                            break
                    else:
                        equals[k] = True

        elif opt == "all":
            concat_over.update(
                set(getattr(datasets[0], subset)) - set(datasets[0].dims)
            )
        elif opt == "minimal":
            pass
        else:
            raise ValueError("unexpected value for %s: %s" % (subset, opt))
    else:
        invalid_vars = [k for k in opt if k not in getattr(datasets[0], subset)]
        if invalid_vars:
            if subset == "coords":
                raise ValueError(
                    "some variables in coords are not coordinates on "
                    "the first dataset: %s" % (invalid_vars,)
                )
            else:
                raise ValueError(
                    "some variables in data_vars are not data variables "
                    "on the first dataset: %s" % (invalid_vars,)
                )
        concat_over.update(opt)

def ensure_common_dims(vars):
    # ensure each variable with the given name shares the same
    # dimensions and the same shape for all of them except along the
    # concat dimension
    common_dims = tuple(pd.unique([d for v in vars for d in v.dims]))
    if dim not in common_dims:
        common_dims = (dim,) + common_dims
    for var, dim_len in zip(vars, concat_dim_lengths):
        if var.dims != common_dims:
            common_shape = tuple(dims_sizes.get(d, dim_len) for d in common_dims)
            var = var.set_dims(common_dims, common_shape)
        yield var

def dataset_merge_method(
    dataset: "Dataset",
    other: "CoercibleMapping",
    overwrite_vars: Union[Hashable, Iterable[Hashable]],
    compat: str,
    join: str,
    fill_value: Any,
) -> _MergeResult:
    """Guts of the Dataset.merge method.
    """
    # we are locked into supporting overwrite_vars for the Dataset.merge
    # method due for backwards compatibility
    # TODO: consider deprecating it?

    if isinstance(overwrite_vars, Iterable) and not isinstance(overwrite_vars, str):
        overwrite_vars = set(overwrite_vars)
    else:
        overwrite_vars = {overwrite_vars}

    if not overwrite_vars:
        objs = [dataset, other]
        priority_arg = None
    elif overwrite_vars == set(other):
        objs = [dataset, other]
        priority_arg = 1
    else:
        other_overwrite: Dict[Hashable, CoercibleValue] = {}
        other_no_overwrite: Dict[Hashable, CoercibleValue] = {}
        for k, v in other.items():
            if k in overwrite_vars:
                other_overwrite[k] = v
            else:
                other_no_overwrite[k] = v
        objs = [dataset, other_no_overwrite, other_overwrite]
        priority_arg = 2

    return merge_core(
        objs, compat, join, priority_arg=priority_arg, fill_value=fill_value
    )

def _get_ansi_code(msg_style: MessageStyle) -> str:
    """Return ANSI escape code corresponding to color and style.

    :param msg_style: the message style

    :raise KeyError: if a nonexistent color or style identifier is given

    :return: the built escape code
    """
    ansi_code = [ANSI_STYLES[effect] for effect in msg_style.style]
    if msg_style.color:
        if msg_style.color.isdigit():
            ansi_code.extend(["38", "5"])
            ansi_code.append(msg_style.color)
        else:
            ansi_code.append(ANSI_COLORS[msg_style.color])
    if ansi_code:
        return ANSI_PREFIX + ";".join(ansi_code) + ANSI_END
    return ""

