def parse(self, args, namespace=None):
    from _pytest._argcomplete import try_argcomplete

    self.optparser = self._getparser()
    try_argcomplete(self.optparser)
    args = [str(x) if isinstance(x, py.path.local) else x for x in args]
    return self.optparser.parse_args(args, namespace=namespace)

def pytest_cmdline_parse(self, pluginmanager, args):
    try:
        self.parse(args)
    except UsageError:

        # Handle --version and --help here in a minimal fashion.
        # This gets done via helpconfig normally, but its
        # pytest_cmdline_main is not called in case of errors.
        if getattr(self.option, "version", False) or "--version" in args:
            from _pytest.helpconfig import showversion

            showversion(self)
        elif (
            getattr(self.option, "help", False) or "--help" in args or "-h" in args
        ):
            self._parser._getparser().print_help()
            sys.stdout.write(
                "\nNOTE: displaying only minimal help due to UsageError.\n\n"
            )

        raise

    return self

def parse(self, args, addopts=True):
    # parse given cmdline arguments into this config object.
    assert not hasattr(
        self, "args"
    ), "can only parse cmdline args at most once per Config object"
    self.hook.pytest_addhooks.call_historic(
        kwargs=dict(pluginmanager=self.pluginmanager)
    )
    self._preparse(args, addopts=addopts)
    # XXX deprecated hook:
    self.hook.pytest_cmdline_preparse(config=self, args=args)
    self._parser.after_preparse = True
    try:
        args = self._parser.parse_setoption(
            args, self.option, namespace=self.option
        )
        if not args:
            if self.invocation_dir == self.rootdir:
                args = self.getini("testpaths")
            if not args:
                args = [str(self.invocation_dir)]
        self.args = args
    except PrintHelp:
        pass

def __init__(self, *names, **attrs):
    """store parms in private vars for use in add_argument"""
    self._attrs = attrs
    self._short_opts = []  # type: List[str]
    self._long_opts = []  # type: List[str]
    self.dest = attrs.get("dest")
    if "%default" in (attrs.get("help") or ""):
        warnings.warn(
            'pytest now uses argparse. "%default" should be'
            ' changed to "%(default)s" ',
            DeprecationWarning,
            stacklevel=3,
        )
    try:
        typ = attrs["type"]
    except KeyError:
        pass
    else:
        # this might raise a keyerror as well, don't want to catch that
        if isinstance(typ, str):
            if typ == "choice":
                warnings.warn(
                    "`type` argument to addoption() is the string %r."
                    " For choices this is optional and can be omitted, "
                    " but when supplied should be a type (for example `str` or `int`)."
                    " (options: %s)" % (typ, names),
                    DeprecationWarning,
                    stacklevel=4,
                )
                # argparse expects a type here take it from
                # the type of the first element
                attrs["type"] = type(attrs["choices"][0])
            else:
                warnings.warn(
                    "`type` argument to addoption() is the string %r, "
                    " but when supplied should be a type (for example `str` or `int`)."
                    " (options: %s)" % (typ, names),
                    DeprecationWarning,
                    stacklevel=4,
                )
                attrs["type"] = Argument._typ_map[typ]
            # used in test_parseopt -> test_parse_defaultgetter
            self.type = attrs["type"]
        else:
            self.type = typ
    try:
        # attribute existence is tested in Config._processopt
        self.default = attrs["default"]
    except KeyError:
        pass
    self._set_opt_strings(names)
    if not self.dest:
        if self._long_opts:
            self.dest = self._long_opts[0][2:].replace("-", "_")
        else:
            try:
                self.dest = self._short_opts[0][1:]
            except IndexError:
                raise ArgumentError("need a long or short option", self)

def _set_opt_strings(self, opts):
    """directly from optparse

    might not be necessary as this is passed to argparse later on"""
    for opt in opts:
        if len(opt) < 2:
            raise ArgumentError(
                "invalid option string %r: "
                "must be at least two characters long" % opt,
                self,
            )
        elif len(opt) == 2:
            if not (opt[0] == "-" and opt[1] != "-"):
                raise ArgumentError(
                    "invalid short option string %r: "
                    "must be of the form -x, (x any non-dash char)" % opt,
                    self,
                )
            self._short_opts.append(opt)
        else:
            if not (opt[0:2] == "--" and opt[2] != "-"):
                raise ArgumentError(
                    "invalid long option string %r: "
                    "must start with --, followed by non-dash" % opt,
                    self,
                )
            self._long_opts.append(opt)

def getbasetemp(self) -> py.path.local:
    """Backward compat wrapper for ``_tmppath_factory.getbasetemp``."""
    return py.path.local(self._tmppath_factory.getbasetemp().resolve())

def get_user() -> Optional[str]:
    """Return the current user name, or None if getuser() does not work
    in the current environment (see #1010)."""
    import getpass

    try:
        return getpass.getuser()
    except (ImportError, KeyError):
        return None

def _mk_tmp(request: FixtureRequest, factory: TempPathFactory) -> Path:
    name = request.node.name
    name = re.sub(r"[\W]", "_", name)
    MAXVAL = 30
    name = name[:MAXVAL]
    return factory.mktemp(name, numbered=True)

def make_numbered_dir(root: Path, prefix: str) -> Path:
    """Create a directory with an increased number as suffix for the given prefix."""
    for i in range(10):
        # try up to 10 times to create the folder
        max_existing = max(map(parse_num, find_suffixes(root, prefix)), default=-1)
        new_number = max_existing + 1
        new_path = root.joinpath(f"{prefix}{new_number}")
        try:
            new_path.mkdir()
        except Exception:
            pass
        else:
            _force_symlink(root, prefix + "current", new_path)
            return new_path
    else:
        raise OSError(
            "could not create numbered dir with prefix "
            "{prefix} in {root} after 10 tries".format(prefix=prefix, root=root)
        )

def ensure_deletable(path: Path, consider_lock_dead_if_created_before: float) -> bool:
    """Check if `path` is deletable based on whether the lock file is expired."""
    if path.is_symlink():
        return False
    lock = get_lock_path(path)
    try:
        if not lock.is_file():
            return True
    except OSError:
        # we might not have access to the lock file at all, in this case assume
        # we don't have access to the entire directory (#7491).
        return False
    try:
        lock_time = lock.stat().st_mtime
    except Exception:
        return False
    else:
        if lock_time < consider_lock_dead_if_created_before:
            # We want to ignore any errors while trying to remove the lock such as:
            # - PermissionDenied, like the file permissions have changed since the lock creation;
            # - FileNotFoundError, in case another pytest process got here first;
            # and any other cause of failure.
            with contextlib.suppress(OSError):
                lock.unlink()
                return True
        return False

def validate_basetemp(path: str) -> str:
    # GH 7119
    msg = "basetemp must not be empty, the current working directory or any parent directory of it"

    # empty path
    if not path:
        raise argparse.ArgumentTypeError(msg)

    def is_ancestor(base: Path, query: Path) -> bool:
        """Return whether query is an ancestor of base."""
        if base == query:
            return True
        for parent in base.parents:
            if parent == query:
                return True
        return False

    # check if path is an ancestor of cwd
    if is_ancestor(Path.cwd(), Path(path).absolute()):
        raise argparse.ArgumentTypeError(msg)

    # check symlinks for ancestors
    if is_ancestor(Path.cwd().resolve(), Path(path).resolve()):
        raise argparse.ArgumentTypeError(msg)

    return path

def locate_config(
    args: Iterable[Path],
) -> Tuple[Optional[Path], Optional[Path], Dict[str, Union[str, List[str]]]]:
    """Search in the list of arguments for a valid ini-file for pytest,
    and return a tuple of (rootdir, inifile, cfg-dict)."""
    config_names = [
        "pytest.ini",
        "pyproject.toml",
        "tox.ini",
        "setup.cfg",
    ]
    args = [x for x in args if not str(x).startswith("-")]
    if not args:
        args = [Path.cwd()]
    for arg in args:
        argpath = absolutepath(arg)
        for base in (argpath, *argpath.parents):
            for config_name in config_names:
                p = base / config_name
                if p.is_file():
                    ini_config = load_config_dict_from_file(p)
                    if ini_config is not None:
                        return base, p, ini_config
    return None, None, {}

def _ensure_relative_to_basetemp(self, basename: str) -> str:
    basename = os.path.normpath(basename)
    if (self.getbasetemp() / basename).resolve().parent != self.getbasetemp():
        raise ValueError(f"{basename} is not a normalized and relative path")
    return basename

def mktemp(self, basename: str, numbered: bool = True) -> py.path.local:
    """Same as :meth:`TempPathFactory.mktemp`, but returns a ``py.path.local`` object."""
    return py.path.local(self._tmppath_factory.mktemp(basename, numbered).resolve())

def _collect_probas(self, X):
    """Collect results from clf.predict calls. """
    return np.asarray([clf.predict_proba(X) for clf in self.estimators_])

def _replace_estimator(self, attr, name, new_val):
    # assumes `name` is a valid estimator name
    new_estimators = list(getattr(self, attr))
    for i, (estimator_name, _) in enumerate(new_estimators):
        if estimator_name == name:
            new_estimators[i] = (name, new_val)
            break
    setattr(self, attr, new_estimators)

def _equal_similarities_and_preferences(S, preference):
    def all_equal_preferences():
        return np.all(preference == preference.flat[0])

    def all_equal_similarities():
        # Create mask to ignore diagonal of S
        mask = np.ones(S.shape, dtype=bool)
        np.fill_diagonal(mask, 0)

        return np.all(S[mask].flat == S[mask].flat[0])

    return all_equal_preferences() and all_equal_similarities()

def all_equal_similarities():
    # Create mask to ignore diagonal of S
    mask = np.ones(S.shape, dtype=bool)
    np.fill_diagonal(mask, 0)

    return np.all(S[mask].flat == S[mask].flat[0])

def prepend_prolog(content: StringList, prolog: str) -> None:
    """Prepend a string to content body as prolog."""
    if prolog:
        pos = 0
        for line in content:
            if docinfo_re.match(line):
                pos += 1
            else:
                break

        if pos > 0:
            # insert a blank line after docinfo
            content.insert(pos, '', '<generated>', 0)
            pos += 1

        # insert prolog (after docinfo if exists)
        for lineno, line in enumerate(prolog.splitlines()):
            content.insert(pos + lineno, line, '<rst_prolog>', lineno)

        content.insert(pos + lineno + 1, '', '<generated>', 0)

def resolve_xref(self, env: BuildEnvironment, fromdocname: str, builder: Builder,
                 typ: str, target: str, node: pending_xref, contnode: Element,
                 ) -> Element | None:
    objtypes = self.objtypes_for_role(typ)
    for objtype in objtypes:
        result = self.objects.get((objtype, target))
        if result:
            todocname, node_id = result
            return make_refnode(builder, fromdocname, todocname, node_id,
                                contnode, target + ' ' + objtype)
    return None

def setup(app: Sphinx) -> dict[str, Any]:
    app.add_source_parser(RSTParser)

    return {
        'version': 'builtin',
        'parallel_read_safe': True,
        'parallel_write_safe': True,
    }

def append_epilog(content: StringList, epilog: str) -> None:
    """Append a string to content body as epilog."""
    if epilog:
        if len(content) > 0:
            source, lineno = content.info(-1)
        else:
            source = '<generated>'
            lineno = 0
        content.append('', source, lineno + 1)
        for lineno, line in enumerate(epilog.splitlines()):
            content.append(line, '<rst_epilog>', lineno)

def note_object(self, objtype: str, name: str, node_id: str, location: Any = None) -> None:
    if (objtype, name) in self.objects:
        docname, node_id = self.objects[objtype, name]
        logger.warning(__('duplicate description of %s %s, other instance in %s') %
                       (objtype, name, docname), location=location)

    self.objects[objtype, name] = (self.env.docname, node_id)

def _resolve_option_xref(self, env: "BuildEnvironment", fromdocname: str,
                         builder: "Builder", typ: str, target: str,
                         node: pending_xref, contnode: Element) -> Element:
    progname = node.get('std:program')
    target = target.strip()
    docname, labelid = self.progoptions.get((progname, target), ('', ''))
    if not docname:
        commands = []
        while ws_re.search(target):
            subcommand, target = ws_re.split(target, 1)
            commands.append(subcommand)
            progname = "-".join(commands)

            docname, labelid = self.progoptions.get((progname, target), ('', ''))
            if docname:
                break
        else:
            return None

    return make_refnode(builder, fromdocname, docname,
                        labelid, contnode)

def warn_missing_reference(app: "Sphinx", domain: Domain, node: pending_xref) -> bool:
    if (domain and domain.name != 'std') or node['reftype'] != 'ref':
        return None
    else:
        target = node['reftarget']
        if target not in domain.anonlabels:  # type: ignore
            msg = __('undefined label: %s')
        else:
            msg = __('Failed to create a cross reference. A title or caption not found: %s')

        logger.warning(msg % target, location=node, type='ref', subtype=node['reftype'])
        return True

def _eval_is_integer(self):
    from sympy.core.logic import fuzzy_and, fuzzy_not
    p, q = self.args
    if fuzzy_and([p.is_integer, q.is_integer, fuzzy_not(q.is_zero)]):
        return True

def _eval_is_nonnegative(self):
    if self.args[1].is_positive:
        return True

def _eval_is_nonpositive(self):
    if self.args[1].is_negative:
        return True

def doit(p, q):
    """Try to return p % q if both are numbers or +/-p is known
    to be less than or equal q.
    """

    if p.is_infinite or q.is_infinite or p is nan or q is nan:
        return nan
    if (p == q or p == -q or
            p.is_Pow and p.exp.is_Integer and p.base == q or
            p.is_integer and q == 1):
        return S.Zero

    if q.is_Number:
        if p.is_Number:
            return (p % q)
        if q == 2:
            if p.is_even:
                return S.Zero
            elif p.is_odd:
                return S.One

    # by ratio
    r = p/q
    try:
        d = int(r)
    except TypeError:
        pass
    else:
        if type(d) is int:
            rv = p - d*q
            if (rv*q < 0) == True:
                rv += q
            return rv

    # by difference
    d = p - q
    if d.is_negative:
        if q.is_negative:
            return d
        elif q.is_positive:
            return p

def preprocess(cls, domain):
    if isinstance(domain, sympy.polys.domains.Domain):
        return domain
    elif hasattr(domain, 'to_domain'):
        return domain.to_domain()
    elif isinstance(domain, string_types):
        if domain in ['Z', 'ZZ']:
            return sympy.polys.domains.ZZ

        if domain in ['Q', 'QQ']:
            return sympy.polys.domains.QQ

        if domain == 'EX':
            return sympy.polys.domains.EX

        r = cls._re_realfield.match(domain)

        if r is not None:
            _, _, prec = r.groups()

            if prec is None:
                return sympy.polys.domains.RR
            else:
                return sympy.polys.domains.RealField(int(prec))

        r = cls._re_complexfield.match(domain)

        if r is not None:
            _, _, prec = r.groups()

            if prec is None:
                return sympy.polys.domains.CC
            else:
                return sympy.polys.domains.ComplexField(int(prec))

        r = cls._re_finitefield.match(domain)

        if r is not None:
            return sympy.polys.domains.FF(int(r.groups()[1]))

        r = cls._re_polynomial.match(domain)

        if r is not None:
            ground, gens = r.groups()

            gens = list(map(sympify, gens.split(',')))

            if ground in ['Z', 'ZZ']:
                return sympy.polys.domains.ZZ.poly_ring(*gens)
            else:
                return sympy.polys.domains.QQ.poly_ring(*gens)

        r = cls._re_fraction.match(domain)

        if r is not None:
            ground, gens = r.groups()

            gens = list(map(sympify, gens.split(',')))

            if ground in ['Z', 'ZZ']:
                return sympy.polys.domains.ZZ.frac_field(*gens)
            else:
                return sympy.polys.domains.QQ.frac_field(*gens)

        r = cls._re_algebraic.match(domain)

        if r is not None:
            gens = list(map(sympify, r.groups()[1].split(',')))
            return sympy.polys.domains.QQ.algebraic_field(*gens)

    raise OptionError('expected a valid domain specification, got %s' % domain)

def preprocess_options(args):
    for option, value in args.items():
        try:
            cls = self.__options__[option]
        except KeyError:
            raise OptionError("'%s' is not a valid option" % option)

        if issubclass(cls, Flag):
            if flags is None or option not in flags:
                if strict:
                    raise OptionError("'%s' flag is not allowed in this context" % option)

        if value is not None:
            self[option] = cls.preprocess(value)

def __init__(self, gens, args, flags=None, strict=False):
    dict.__init__(self)

    if gens and args.get('gens', ()):
        raise OptionError(
            "both '*gens' and keyword argument 'gens' supplied")
    elif gens:
        args = dict(args)
        args['gens'] = gens

    defaults = args.pop('defaults', {})

    def preprocess_options(args):
        for option, value in args.items():
            try:
                cls = self.__options__[option]
            except KeyError:
                raise OptionError("'%s' is not a valid option" % option)

            if issubclass(cls, Flag):
                if flags is None or option not in flags:
                    if strict:
                        raise OptionError("'%s' flag is not allowed in this context" % option)

            if value is not None:
                self[option] = cls.preprocess(value)

    preprocess_options(args)

    for key, value in dict(defaults).items():
        if key in self:
            del defaults[key]
        else:
            for option in self.keys():
                cls = self.__options__[option]

                if key in cls.excludes:
                    del defaults[key]
                    break

    preprocess_options(defaults)

    for option in self.keys():
        cls = self.__options__[option]

        for require_option in cls.requires:
            if self.get(require_option) is None:
                raise OptionError("'%s' option is only allowed together with '%s'" % (option, require_option))

        for exclude_option in cls.excludes:
            if self.get(exclude_option) is not None:
                raise OptionError("'%s' option is not allowed together with '%s'" % (option, exclude_option))

    for option in self.__order__:
        self.__options__[option].postprocess(self)

def __new__(cls, rep, *gens, **args):
    """Create a new polynomial instance out of something useful. """
    opt = options.build_options(gens, args)

    if 'order' in opt:
        raise NotImplementedError("'order' keyword is not implemented yet")

    if iterable(rep, exclude=str):
        if isinstance(rep, dict):
            return cls._from_dict(rep, opt)
        else:
            return cls._from_list(list(rep), opt)
    else:
        rep = sympify(rep)

        if rep.is_Poly:
            return cls._from_poly(rep, opt)
        else:
            return cls._from_expr(rep, opt)

def preprocess(cls, gens):
    if isinstance(gens, Basic):
        gens = (gens,)
    elif len(gens) == 1 and hasattr(gens[0], '__iter__'):
        gens = gens[0]

    if gens == (None,):
        gens = ()
    elif has_dups(gens):
        raise GeneratorsError("duplicated generators: %s" % str(gens))
    elif any(gen.is_commutative is False for gen in gens):
        raise GeneratorsError("non-commutative generators: %s" % str(gens))

    return tuple(gens)

def _print_Sum(self, expr):
    if len(expr.limits) == 1:
        tex = r"\sum_{%s=%s}^{%s} " % \
            tuple([ self._print(i) for i in expr.limits[0] ])
    else:
        def _format_ineq(l):
            return r"%s \leq %s \leq %s" % \
                tuple([self._print(s) for s in (l[1], l[0], l[2])])

        tex = r"\sum_{\substack{%s}} " % \
            str.join('\\\\', [ _format_ineq(l) for l in expr.limits ])

    if isinstance(expr.function, Add):
        tex += r"\left(%s\right)" % self._print(expr.function)
    else:
        tex += self._print(expr.function)

    return tex

def _print_Product(self, expr):
    if len(expr.limits) == 1:
        tex = r"\prod_{%s=%s}^{%s} " % \
            tuple([ self._print(i) for i in expr.limits[0] ])
    else:
        def _format_ineq(l):
            return r"%s \leq %s \leq %s" % \
                tuple([self._print(s) for s in (l[1], l[0], l[2])])

        tex = r"\prod_{\substack{%s}} " % \
            str.join('\\\\', [ _format_ineq(l) for l in expr.limits ])

    if isinstance(expr.function, Add):
        tex += r"\left(%s\right)" % self._print(expr.function)
    else:
        tex += self._print(expr.function)

    return tex

def _print_Add(self, expr, order=None):
    if self.order == 'none':
        terms = list(expr.args)
    else:
        terms = self._as_ordered_terms(expr, order=order)

    tex = ""
    for i, term in enumerate(terms):
        if i == 0:
            pass
        elif _coeff_isneg(term):
            tex += " - "
            term = -term
        else:
            tex += " + "
        term_tex = self._print(term)
        if self._needs_add_brackets(term):
            term_tex = r"\left(%s\right)" % term_tex
        tex += term_tex

    return tex

def _print_Pow(self, expr):
    # Treat x**Rational(1,n) as special case
    if expr.exp.is_Rational and abs(expr.exp.p) == 1 and expr.exp.q != 1:
        base = self._print(expr.base)
        expq = expr.exp.q

        if expq == 2:
            tex = r"\sqrt{%s}" % base
        elif self._settings['itex']:
            tex = r"\root{%d}{%s}" % (expq, base)
        else:
            tex = r"\sqrt[%d]{%s}" % (expq, base)

        if expr.exp.is_negative:
            return r"\frac{1}{%s}" % tex
        else:
            return tex
    elif self._settings['fold_frac_powers'] \
        and expr.exp.is_Rational \
            and expr.exp.q != 1:
        base, p, q = self.parenthesize(expr.base, PRECEDENCE['Pow']), expr.exp.p, expr.exp.q
        # issue #12886: add parentheses for superscripts raised to powers
        if '^' in base and expr.base.is_Symbol:
            base = r"\left(%s\right)" % base
        if expr.base.is_Function:
            return self._print(expr.base, exp="%s/%s" % (p, q))
        return r"%s^{%s/%s}" % (base, p, q)
    elif expr.exp.is_Rational and expr.exp.is_negative and expr.base.is_commutative:
        # special case for 1^(-x), issue 9216
        if expr.base == 1:
            return r"%s^{%s}" % (expr.base, expr.exp)
        # things like 1/x
        return self._print_Mul(expr)
    else:
        if expr.base.is_Function:
            return self._print(expr.base, exp=self._print(expr.exp))
        else:
            tex = r"%s^{%s}"
            exp = self._print(expr.exp)
            # issue #12886: add parentheses around superscripts raised to powers
            base = self.parenthesize(expr.base, PRECEDENCE['Pow'])
            if '^' in base and expr.base.is_Symbol:
                base = r"\left(%s\right)" % base
            elif isinstance(expr.base, Derivative
                    ) and base.startswith(r'\left('
                    ) and re.match(r'\\left\(\\d?d?dot', base
                    ) and base.endswith(r'\right)'):
                # don't use parentheses around dotted derivative
                base = base[6: -7]  # remove outermost added parens

            return tex % (base, exp)

def _print_MatrixElement(self, expr):
    return self.parenthesize(expr.parent, PRECEDENCE["Atom"], strict=True) \
        + '_{%s, %s}' % (expr.i, expr.j)

def _print_Derivative(self, expr):
    if requires_partial(expr):
        diff_symbol = r'\partial'
    else:
        diff_symbol = r'd'

    tex = ""
    dim = 0
    for x, num in reversed(expr.variable_count):
        dim += num
        if num == 1:
            tex += r"%s %s" % (diff_symbol, self._print(x))
        else:
            tex += r"%s %s^{%s}" % (diff_symbol, self._print(x), num)

    if dim == 1:
        tex = r"\frac{%s}{%s}" % (diff_symbol, tex)
    else:
        tex = r"\frac{%s^{%s}}{%s}" % (diff_symbol, dim, tex)

    return r"%s %s" % (tex, self.parenthesize(expr.expr, PRECEDENCE["Mul"], strict=True))

def __eq__(self, other):
    try:
        other = sympify(other)
        if not isinstance(other, Expr):
            return False
    except (SympifyError, SyntaxError):
        return False
    # check for pure number expr
    if  not (self.is_Number and other.is_Number) and (
            type(self) != type(other)):
        return False
    a, b = self._hashable_content(), other._hashable_content()
    if a != b:
        return False
    # check number *in* an expression
    for a, b in zip(a, b):
        if not isinstance(a, Expr):
            continue
        if a.is_Number and type(a) != type(b):
            return False
    return True

def stringify_expr(s, local_dict, global_dict, transformations):
    """
    Converts the string ``s`` to Python code, in ``local_dict``

    Generally, ``parse_expr`` should be used.
    """

    tokens = []
    input_code = StringIO(s.strip())
    for toknum, tokval, _, _, _ in generate_tokens(input_code.readline):
        tokens.append((toknum, tokval))

    for transform in transformations:
        tokens = transform(tokens, local_dict, global_dict)

    return untokenize(tokens)

def get_dimensional_expr(self, expr):
    from sympy import Mul, Add, Pow, Derivative
    from sympy import Function
    from sympy.physics.units import Quantity
    if isinstance(expr, Mul):
        return Mul(*[self.get_dimensional_expr(i) for i in expr.args])
    elif isinstance(expr, Pow):
        return self.get_dimensional_expr(expr.base) ** expr.exp
    elif isinstance(expr, Add):
        return self.get_dimensional_expr(expr.args[0])
    elif isinstance(expr, Derivative):
        dim = self.get_dimensional_expr(expr.expr)
        for independent, count in expr.variable_count:
            dim /= self.get_dimensional_expr(independent)**count
        return dim
    elif isinstance(expr, Function):
        args = [self.get_dimensional_expr(arg) for arg in expr.args]
        if all(i == 1 for i in args):
            return S.One
        return expr.func(*args)
    elif isinstance(expr, Quantity):
        return self.get_quantity_dimension(expr).name
    return S.One

def check_dimensions(expr, unit_system="SI"):
    """Return expr if there are not unitless values added to
    dimensional quantities, else raise a ValueError."""
    # the case of adding a number to a dimensional quantity
    # is ignored for the sake of SymPy core routines, so this
    # function will raise an error now if such an addend is
    # found.
    # Also, when doing substitutions, multiplicative constants
    # might be introduced, so remove those now

    from sympy.physics.units import UnitSystem
    unit_system = UnitSystem.get_unit_system(unit_system)

    adds = expr.atoms(Add)
    DIM_OF = unit_system.get_dimension_system().get_dimensional_dependencies
    for a in adds:
        deset = set()
        for ai in a.args:
            if ai.is_number:
                deset.add(())
                continue
            dims = []
            skip = False
            for i in Mul.make_args(ai):
                if i.has(Quantity):
                    i = Dimension(unit_system.get_dimensional_expr(i))
                if i.has(Dimension):
                    dims.extend(DIM_OF(i).items())
                elif i.free_symbols:
                    skip = True
                    break
            if not skip:
                deset.add(tuple(sorted(dims)))
                if len(deset) > 1:
                    raise ValueError(
                        "addends have incompatible dimensions")

    # clear multiplicative constants on Dimensions which may be
    # left after substitution
    reps = {}
    for m in expr.atoms(Mul):
        if any(isinstance(i, Dimension) for i in m.args):
            reps[m] = m.func(*[
                i for i in m.args if not i.is_number])

    return expr.xreplace(reps)

def get_total_scale_factor(expr):
    if isinstance(expr, Mul):
        return reduce(lambda x, y: x * y, [get_total_scale_factor(i) for i in expr.args])
    elif isinstance(expr, Pow):
        return get_total_scale_factor(expr.base) ** expr.exp
    elif isinstance(expr, Quantity):
        return unit_system.get_quantity_scale_factor(expr)
    return expr

def get_quantity_dimension(self, unit):
    qdm = self.get_dimension_system()._quantity_dimension_map
    if unit in qdm:
        return qdm[unit]
    return super().get_quantity_dimension(unit)

def __new__(cls, *args, **kwargs):
    evaluate = kwargs.get('evaluate', global_parameters.evaluate)
    on_morph = kwargs.get('on_morph', 'ignore')

    # unpack into coords
    coords = args[0] if len(args) == 1 else args

    # check args and handle quickly handle Point instances
    if isinstance(coords, Point):
        # even if we're mutating the dimension of a point, we
        # don't reevaluate its coordinates
        evaluate = False
        if len(coords) == kwargs.get('dim', len(coords)):
            return coords

    if not is_sequence(coords):
        raise TypeError(filldedent('''
            Expecting sequence of coordinates, not `{}`'''
                                   .format(func_name(coords))))
    # A point where only `dim` is specified is initialized
    # to zeros.
    if len(coords) == 0 and kwargs.get('dim', None):
        coords = (S.Zero,)*kwargs.get('dim')

    coords = Tuple(*coords)
    dim = kwargs.get('dim', len(coords))

    if len(coords) < 2:
        raise ValueError(filldedent('''
            Point requires 2 or more coordinates or
            keyword `dim` > 1.'''))
    if len(coords) != dim:
        message = ("Dimension of {} needs to be changed "
                   "from {} to {}.").format(coords, len(coords), dim)
        if on_morph == 'ignore':
            pass
        elif on_morph == "error":
            raise ValueError(message)
        elif on_morph == 'warn':
            warnings.warn(message)
        else:
            raise ValueError(filldedent('''
                    on_morph value should be 'error',
                    'warn' or 'ignore'.'''))
    if any(coords[dim:]):
        raise ValueError('Nonzero coordinates cannot be removed.')
    if any(a.is_number and im(a) for a in coords):
        raise ValueError('Imaginary coordinates are not permitted.')
    if not all(isinstance(a, Expr) for a in coords):
        raise TypeError('Coordinates must be valid SymPy expressions.')

    # pad with zeros appropriately
    coords = coords[:dim] + (S.Zero,)*(dim - len(coords))

    # Turn any Floats into rationals and simplify
    # any expressions before we instantiate
    if evaluate:
        coords = coords.xreplace({
            f: simplify(nsimplify(f, rational=True))
             for f in coords.atoms(Float)})

    # return 2D or 3D instances
    if len(coords) == 2:
        kwargs['_nocheck'] = True
        return Point2D(*coords, **kwargs)
    elif len(coords) == 3:
        kwargs['_nocheck'] = True
        return Point3D(*coords, **kwargs)

    # the general Point
    return GeometryEntity.__new__(cls, *coords)

def visit_Call(self, node):
    new_node = self.generic_visit(node)
    if isinstance(node.func, ast.Name) and node.func.id in self.functions:
        new_node.keywords.append(ast.keyword(arg='evaluate', value=ast.NameConstant(value=False, ctx=ast.Load())))
    return new_node

def __truediv__(self, other):
    if not hasattr(other, "scale_factor"):
        return super().__truediv__(other)

    fact = self.scale_factor / other.scale_factor

    if fact == 1:
        return 1
    elif isinstance(other, Prefix):
        for p in PREFIXES:
            if PREFIXES[p].scale_factor == fact:
                return PREFIXES[p]
        return fact

    return self.scale_factor / other

def __rtruediv__(self, other):
    if other == 1:
        for p in PREFIXES:
            if PREFIXES[p].scale_factor == 1 / self.scale_factor:
                return PREFIXES[p]
    return other / self.scale_factor

def dimension(self):
    from sympy.physics.units import UnitSystem
    unit_system = UnitSystem.get_default_unit_system()
    return unit_system.get_quantity_dimension(self)

def get_quantity_dimension(self, unit):
    qdm = self.get_dimension_system()._quantity_dimension_map
    if unit in qdm:
        return qdm[unit]
    return super().get_quantity_dimension(unit)

def get_quantity_scale_factor(self, unit):
    qsfm = self.get_dimension_system()._quantity_scale_factors
    if unit in qsfm:
        return qsfm[unit]
    return super().get_quantity_scale_factor(unit)

def _get_kernel(self, X, Y=None):
    if callable(self.kernel):
        params = self.kernel_params or {}
    else:
        params = {"gamma": self.gamma,
                  "degree": self.degree,
                  "coef0": self.coef0}
    return pairwise_kernels(X, Y, metric=self.kernel,
                            filter_params=True, n_jobs=self.n_jobs,
                            **params)

def named_steps(self):
    # Use Bunch object to improve autocomplete
    return Bunch(**dict(self.steps))

def _final_estimator(self):
    estimator = self.steps[-1][1]
    return 'passthrough' if estimator is None else estimator

def _fit(self, X, y=None, **fit_params):
    # shallow copy of steps - this should really be steps_
    self.steps = list(self.steps)
    self._validate_steps()
    # Setup the memory
    memory = check_memory(self.memory)

    fit_transform_one_cached = memory.cache(_fit_transform_one)

    fit_params_steps = {name: {} for name, step in self.steps
                        if step is not None}
    for pname, pval in fit_params.items():
        step, param = pname.split('__', 1)
        fit_params_steps[step][param] = pval
    Xt = X
    for step_idx, name, transformer in self._iter(with_final=False):
        if hasattr(memory, 'location'):
            # joblib >= 0.12
            if memory.location is None:
                # we do not clone when caching is disabled to
                # preserve backward compatibility
                cloned_transformer = transformer
            else:
                cloned_transformer = clone(transformer)
        elif hasattr(memory, 'cachedir'):
            # joblib < 0.11
            if memory.cachedir is None:
                # we do not clone when caching is disabled to
                # preserve backward compatibility
                cloned_transformer = transformer
            else:
                cloned_transformer = clone(transformer)
        else:
            cloned_transformer = clone(transformer)
        # Fit or load from cache the current transfomer
        Xt, fitted_transformer = fit_transform_one_cached(
            cloned_transformer, Xt, y, None,
            **fit_params_steps[name])
        # Replace the transformer of the step with the fitted
        # transformer. This is necessary when loading the transformer
        # from the cache.
        self.steps[step_idx] = (name, fitted_transformer)
    if self._final_estimator == 'passthrough':
        return Xt, {}
    return Xt, fit_params_steps[self.steps[-1][0]]

def _transform(self, X):
    Xt = X
    for _, _, transform in self._iter():
        Xt = transform.transform(Xt)
    return Xt

def _validate_names(self, names):
    if len(set(names)) != len(names):
        raise ValueError('Names provided are not unique: '
                         '{0!r}'.format(list(names)))
    invalid_names = set(names).intersection(self.get_params(deep=False))
    if invalid_names:
        raise ValueError('Estimator names conflict with constructor '
                         'arguments: {0!r}'.format(sorted(invalid_names)))
    invalid_names = [name for name in names if '__' in name]
    if invalid_names:
        raise ValueError('Estimator names must not contain __: got '
                         '{0!r}'.format(invalid_names))

def _pprint_estimator(self, object, stream, indent, allowance, context,
                      level):
    stream.write(object.__class__.__name__ + '(')
    if self._indent_at_name:
        indent += len(object.__class__.__name__)

    if self._changed_only:
        params = _changed_params(object)
    else:
        params = object.get_params(deep=False)

    params = OrderedDict((name, val)
                         for (name, val) in sorted(params.items()))

    self._format_params(params.items(), stream, indent, allowance + 1,
                        context, level)
    stream.write(')')

def _format_dict_items(self, items, stream, indent, allowance, context,
                       level):
    return self._format_params_or_dict_items(
        items, stream, indent, allowance, context, level, is_dict=True)

def _num_samples(x):
    """Return number of samples in array-like x."""
    message = 'Expected sequence or array-like, got %s' % type(x)
    if hasattr(x, 'fit') and callable(x.fit):
        # Don't get num_samples from an ensembles length!
        raise TypeError(message)

    if not hasattr(x, '__len__') and not hasattr(x, 'shape'):
        if hasattr(x, '__array__'):
            x = np.asarray(x)
        else:
            raise TypeError(message)

    if hasattr(x, 'shape') and x.shape is not None:
        if len(x.shape) == 0:
            raise TypeError("Singleton array %r cannot be considered"
                            " a valid collection." % x)
        # Check that shape is returning an integer or default to len
        # Dask dataframes may not return numeric shape[0] value
        if isinstance(x.shape[0], numbers.Integral):
            return x.shape[0]

    try:
        return len(x)
    except TypeError:
        raise TypeError(message)

def _pandas_dtype_needs_early_conversion(pd_dtype):
    """Return True if pandas extension pd_dtype need to be converted early."""
    # Check these early for pandas versions without extension dtypes
    from pandas.api.types import (
        is_bool_dtype,
        is_sparse,
        is_float_dtype,
        is_integer_dtype,
    )

    if is_bool_dtype(pd_dtype):
        # bool and extension booleans need early converstion because __array__
        # converts mixed dtype dataframes into object dtypes
        return True

    if is_sparse(pd_dtype):
        # Sparse arrays will be converted later in `check_array`
        return False

    try:
        from pandas.api.types import is_extension_array_dtype
    except ImportError:
        return False

    if is_sparse(pd_dtype) or not is_extension_array_dtype(pd_dtype):
        # Sparse arrays will be converted later in `check_array`
        # Only handle extension arrays for integer and floats
        return False
    elif is_float_dtype(pd_dtype):
        # Float ndarrays can normally support nans. They need to be converted
        # first to map pd.NA to np.nan
        return True
    elif is_integer_dtype(pd_dtype):
        # XXX: Warn when converting from a high integer to a float
        return True

    return False

