def _make_indexable(iterable):
    """Ensure iterable supports indexing or convert to an indexable variant.

    Convert sparse matrices to csr and other non-indexable iterable to arrays.
    Let `None` and indexable objects (e.g. pandas dataframes) pass unchanged.

    Parameters
    ----------
    iterable : {list, dataframe, ndarray, sparse matrix} or None
        Object to be converted to an indexable iterable.
    """
    if sp.issparse(iterable):
        return iterable.tocsr()
    elif hasattr(iterable, "__getitem__") or hasattr(iterable, "iloc"):
        return iterable
    elif iterable is None:
        return iterable
    return np.array(iterable)

def format_args(self, **kwargs: Any) -> str:
    if self.config.autodoc_typehints in ('none', 'description'):
        kwargs.setdefault('show_annotation', False)
    if self.config.autodoc_typehints_format == "short":
        kwargs.setdefault('unqualified_typehints', True)

    try:
        self.env.app.emit('autodoc-before-process-signature', self.object, False)
        sig = inspect.signature(self.object, type_aliases=self.config.autodoc_type_aliases)
        args = stringify_signature(sig, **kwargs)
    except TypeError as exc:
        logger.warning(__("Failed to get a function signature for %s: %s"),
                       self.fullname, exc)
        return None
    except ValueError:
        args = ''

    if self.config.strip_signature_backslash:
        # escape backslashes for reST
        args = args.replace('\\', '\\\\')
    return args

def format_args(self, **kwargs: Any) -> str:
    if self.config.autodoc_typehints in ('none', 'description'):
        kwargs.setdefault('show_annotation', False)
    if self.config.autodoc_typehints_format == "short":
        kwargs.setdefault('unqualified_typehints', True)

    try:
        self._signature_class, self._signature_method_name, sig = self._get_signature()
    except TypeError as exc:
        # __signature__ attribute contained junk
        logger.warning(__("Failed to get a constructor signature for %s: %s"),
                       self.fullname, exc)
        return None

    if sig is None:
        return None

    return stringify_signature(sig, show_return_annotation=False, **kwargs)

def get_user_defined_function_or_method(obj: Any, attr: str) -> Any:
    """ Get the `attr` function or method from `obj`, if it is user-defined. """
    if inspect.is_builtin_class_method(obj, attr):
        return None
    attr = self.get_attr(obj, attr, None)
    if not (inspect.ismethod(attr) or inspect.isfunction(attr)):
        return None
    return attr

def format_signature(self, **kwargs: Any) -> str:
    if self.args is None and self.config.autodoc_docstring_signature:  # type: ignore
        # only act if a signature is not explicitly given already, and if
        # the feature is enabled
        result = self._find_signature()
        if result is not None:
            self.args, self.retann = result
    sig = super().format_signature(**kwargs)  # type: ignore
    if self._signatures:
        return "\n".join([sig] + self._signatures)
    else:
        return sig

def _find_signature(self) -> Tuple[str, str]:
    # candidates of the object name
    valid_names = [self.objpath[-1]]  # type: ignore
    if isinstance(self, ClassDocumenter):
        valid_names.append('__init__')
        if hasattr(self.object, '__mro__'):
            valid_names.extend(cls.__name__ for cls in self.object.__mro__)

    docstrings = self.get_doc()
    if docstrings is None:
        return None, None
    self._new_docstrings = docstrings[:]
    self._signatures = []
    result = None
    for i, doclines in enumerate(docstrings):
        for j, line in enumerate(doclines):
            if not line:
                # no lines in docstring, no match
                break

            if line.endswith('\\'):
                line = line.rstrip('\\').rstrip()

            # match first line of docstring against signature RE
            match = py_ext_sig_re.match(line)
            if not match:
                break
            exmod, path, base, args, retann = match.groups()

            # the base name must match ours
            if base not in valid_names:
                break

            # re-prepare docstring to ignore more leading indentation
            tab_width = self.directive.state.document.settings.tab_width  # type: ignore
            self._new_docstrings[i] = prepare_docstring('\n'.join(doclines[j + 1:]),
                                                        tab_width)

            if result is None:
                # first signature
                result = args, retann
            else:
                # subsequent signatures
                self._signatures.append("(%s) -> %s" % (args, retann))

        if result:
            # finish the loop when signature found
            break

    return result

def create_index(self, builder: Builder, group_entries: bool = True,
                 _fixre: Pattern = re.compile(r'(.*) ([(][^()]*[)])')
                 ) -> List[Tuple[str, List[Tuple[str, Any]]]]:
    """Create the real index from the collected index entries."""
    new = {}  # type: Dict[str, List]

    def add_entry(word: str, subword: str, main: str, link: bool = True,
                  dic: Dict = new, key: str = None) -> None:
        # Force the word to be unicode if it's a ASCII bytestring.
        # This will solve problems with unicode normalization later.
        # For instance the RFC role will add bytestrings at the moment
        word = str(word)
        entry = dic.get(word)
        if not entry:
            dic[word] = entry = [[], {}, key]
        if subword:
            add_entry(subword, '', main, link=link, dic=entry[1], key=key)
        elif link:
            try:
                uri = builder.get_relative_uri('genindex', fn) + '#' + tid
            except NoUri:
                pass
            else:
                entry[0].append((main, uri))

    domain = cast(IndexDomain, self.env.get_domain('index'))
    for fn, entries in domain.entries.items():
        # new entry types must be listed in directives/other.py!
        for type, value, tid, main, index_key in entries:
            try:
                if type == 'single':
                    try:
                        entry, subentry = split_into(2, 'single', value)
                    except ValueError:
                        entry, = split_into(1, 'single', value)
                        subentry = ''
                    add_entry(entry, subentry, main, key=index_key)
                elif type == 'pair':
                    first, second = split_into(2, 'pair', value)
                    add_entry(first, second, main, key=index_key)
                    add_entry(second, first, main, key=index_key)
                elif type == 'triple':
                    first, second, third = split_into(3, 'triple', value)
                    add_entry(first, second + ' ' + third, main, key=index_key)
                    add_entry(second, third + ', ' + first, main, key=index_key)
                    add_entry(third, first + ' ' + second, main, key=index_key)
                elif type == 'see':
                    first, second = split_into(2, 'see', value)
                    add_entry(first, _('see %s') % second, None,
                              link=False, key=index_key)
                elif type == 'seealso':
                    first, second = split_into(2, 'see', value)
                    add_entry(first, _('see also %s') % second, None,
                              link=False, key=index_key)
                else:
                    logger.warning(__('unknown index entry type %r'), type, location=fn)
            except ValueError as err:
                logger.warning(str(err), location=fn)

    # sort the index entries for same keyword.
    def keyfunc0(entry: Tuple[str, str]) -> Tuple[bool, str]:
        main, uri = entry
        return (not main, uri)  # show main entries at first

    for indexentry in new.values():
        indexentry[0].sort(key=keyfunc0)
        for subentry in indexentry[1].values():
            subentry[0].sort(key=keyfunc0)  # type: ignore

    # sort the index entries; put all symbols at the front, even those
    # following the letters in ASCII, this is where the chr(127) comes from
    def keyfunc(entry: Tuple[str, List]) -> Tuple[str, str]:
        key, (void, void, category_key) = entry
        if category_key:
            # using specified category key to sort
            key = category_key
        lckey = unicodedata.normalize('NFD', key.lower())
        if lckey.startswith('\N{RIGHT-TO-LEFT MARK}'):
            lckey = lckey[1:]
        if lckey[0:1].isalpha() or lckey.startswith('_'):
            lckey = chr(127) + lckey
        # ensure a determinstic order *within* letters by also sorting on
        # the entry itself
        return (lckey, entry[0])
    newlist = sorted(new.items(), key=keyfunc)

    if group_entries:
        # fixup entries: transform
        #   func() (in module foo)
        #   func() (in module bar)
        # into
        #   func()
        #     (in module foo)
        #     (in module bar)
        oldkey = ''
        oldsubitems = None  # type: Dict[str, List]
        i = 0
        while i < len(newlist):
            key, (targets, subitems, _key) = newlist[i]
            # cannot move if it has subitems; structure gets too complex
            if not subitems:
                m = _fixre.match(key)
                if m:
                    if oldkey == m.group(1):
                        # prefixes match: add entry as subitem of the
                        # previous entry
                        oldsubitems.setdefault(m.group(2), [[], {}, _key])[0].\
                            extend(targets)
                        del newlist[i]
                        continue
                    oldkey = m.group(1)
                else:
                    oldkey = key
            oldsubitems = subitems
            i += 1

    # sort the sub-index entries
    def keyfunc2(entry: Tuple[str, List]) -> str:
        key = unicodedata.normalize('NFD', entry[0].lower())
        if key.startswith('\N{RIGHT-TO-LEFT MARK}'):
            key = key[1:]
        if key[0:1].isalpha() or key.startswith('_'):
            key = chr(127) + key
        return key

    # group the entries by letter
    def keyfunc3(item: Tuple[str, List]) -> str:
        # hack: mutating the subitems dicts to a list in the keyfunc
        k, v = item
        v[1] = sorted(((si, se) for (si, (se, void, void)) in v[1].items()),
                      key=keyfunc2)
        if v[2] is None:
            # now calculate the key
            if k.startswith('\N{RIGHT-TO-LEFT MARK}'):
                k = k[1:]
            letter = unicodedata.normalize('NFD', k[0])[0].upper()
            if letter.isalpha() or letter == '_':
                return letter
            else:
                # get all other symbols under one heading
                return _('Symbols')
        else:
            return v[2]
    return [(key_, list(group))
            for (key_, group) in groupby(newlist, keyfunc3)]

def setup(app: Sphinx) -> Dict[str, Any]:
    app.add_env_collector(IndexEntriesCollector)

    return {
        'version': 'builtin',
        'parallel_read_safe': True,
        'parallel_write_safe': True,
    }

def process_doc(self, env: BuildEnvironment, docname: str, document: Node) -> None:
    """Process a document after it is read by the environment."""
    entries = self.entries.setdefault(env.docname, [])
    for node in document.traverse(addnodes.index):
        try:
            for entry in node['entries']:
                split_index_msg(entry[0], entry[1])
        except ValueError as exc:
            logger.warning(str(exc), location=node)
            node.parent.remove(node)
        else:
            for entry in node['entries']:
                entries.append(entry)

def assign_figure_numbers(self, env: BuildEnvironment) -> List[str]:
    """Assign a figure number to each figure under a numbered toctree."""

    rewrite_needed = []

    assigned = set()  # type: Set[str]
    old_fignumbers = env.toc_fignumbers
    env.toc_fignumbers = {}
    fignum_counter = {}  # type: Dict[str, Dict[Tuple[int, ...], int]]

    def get_figtype(node: Node) -> str:
        for domain in env.domains.values():
            figtype = domain.get_enumerable_node_type(node)
            if domain.name == 'std' and not domain.get_numfig_title(node):  # type: ignore
                # Skip if uncaptioned node
                continue

            if figtype:
                return figtype

        return None

    def get_section_number(docname: str, section: nodes.section) -> Tuple[int, ...]:
        anchorname = '#' + section['ids'][0]
        secnumbers = env.toc_secnumbers.get(docname, {})
        if anchorname in secnumbers:
            secnum = secnumbers.get(anchorname)
        else:
            secnum = secnumbers.get('')

        return secnum or tuple()

    def get_next_fignumber(figtype: str, secnum: Tuple[int, ...]) -> Tuple[int, ...]:
        counter = fignum_counter.setdefault(figtype, {})

        secnum = secnum[:env.config.numfig_secnum_depth]
        counter[secnum] = counter.get(secnum, 0) + 1
        return secnum + (counter[secnum],)

    def register_fignumber(docname: str, secnum: Tuple[int, ...],
                           figtype: str, fignode: Element) -> None:
        env.toc_fignumbers.setdefault(docname, {})
        fignumbers = env.toc_fignumbers[docname].setdefault(figtype, {})
        figure_id = fignode['ids'][0]

        fignumbers[figure_id] = get_next_fignumber(figtype, secnum)

    def _walk_doctree(docname: str, doctree: Element, secnum: Tuple[int, ...]) -> None:
        for subnode in doctree.children:
            if isinstance(subnode, nodes.section):
                next_secnum = get_section_number(docname, subnode)
                if next_secnum:
                    _walk_doctree(docname, subnode, next_secnum)
                else:
                    _walk_doctree(docname, subnode, secnum)
            elif isinstance(subnode, addnodes.toctree):
                for title, subdocname in subnode['entries']:
                    if url_re.match(subdocname) or subdocname == 'self':
                        # don't mess with those
                        continue

                    _walk_doc(subdocname, secnum)
            elif isinstance(subnode, nodes.Element):
                figtype = get_figtype(subnode)
                if figtype and subnode['ids']:
                    register_fignumber(docname, secnum, figtype, subnode)

                _walk_doctree(docname, subnode, secnum)

    def _walk_doc(docname: str, secnum: Tuple[int, ...]) -> None:
        if docname not in assigned:
            assigned.add(docname)
            doctree = env.get_doctree(docname)
            _walk_doctree(docname, doctree, secnum)

    if env.config.numfig:
        _walk_doc(env.config.master_doc, tuple())
        for docname, fignums in env.toc_fignumbers.items():
            if fignums != old_fignumbers.get(docname):
                rewrite_needed.append(docname)

    return rewrite_needed

def get_next_fignumber(figtype: str, secnum: Tuple[int, ...]) -> Tuple[int, ...]:
    counter = fignum_counter.setdefault(figtype, {})

    secnum = secnum[:env.config.numfig_secnum_depth]
    counter[secnum] = counter.get(secnum, 0) + 1
    return secnum + (counter[secnum],)

def assemble_toc_fignumbers(self) -> Dict[str, Dict[str, Dict[str, Tuple[int, ...]]]]:
    # Assemble toc_fignumbers to resolve figure numbers on SingleHTML.
    # Merge all fignumbers to single fignumber.
    #
    # Note: current Sphinx has refid confliction in singlehtml mode.
    #       To avoid the problem, it replaces key of secnumbers to
    #       tuple of docname and refid.
    #
    #       There are related codes in inline_all_toctres() and
    #       HTMLTranslter#add_fignumber().
    new_fignumbers = {}  # type: Dict[str, Dict[str, Tuple[int, ...]]]
    # {'foo': {'figure': {'id2': (2,), 'id1': (1,)}}, 'bar': {'figure': {'id1': (3,)}}}
    for docname, fignumlist in self.env.toc_fignumbers.items():
        for figtype, fignums in fignumlist.items():
            alias = "%s/%s" % (docname, figtype)
            new_fignumbers.setdefault(alias, {})
            for id, fignum in fignums.items():
                new_fignumbers[alias][id] = fignum

    return {self.config.master_doc: new_fignumbers}

def get_module_members(self) -> Dict[str, ObjectMember]:
    """Get members of target module."""
    if self.analyzer:
        attr_docs = self.analyzer.attr_docs
    else:
        attr_docs = {}

    members = {}  # type: Dict[str, ObjectMember]
    for name in dir(self.object):
        try:
            value = safe_getattr(self.object, name, None)
            docstring = attr_docs.get(('', name), [])
            members[name] = ObjectMember(name, value, docstring="\n".join(docstring))
        except AttributeError:
            continue

    # annotation only member (ex. attr: int)
    try:
        for name in inspect.getannotations(self.object):
            if name not in members:
                docstring = attr_docs.get(('', name), [])
                members[name] = ObjectMember(name, INSTANCEATTR,
                                             docstring="\n".join(docstring))
    except AttributeError:
        pass

    return members

def get_object_members(self, want_all: bool) -> Tuple[bool, ObjectMembers]:
    members = self.get_module_members()
    if want_all:
        if not self.__all__:
            # for implicit module members, check __module__ to avoid
            # documenting imported objects
            return True, list(members.values())
        else:
            for member in members.values():
                if member.__name__ not in self.__all__:
                    member.skipped = True

            return False, list(members.values())
    else:
        memberlist = self.options.members or []
        ret = []
        for name in memberlist:
            if name in members:
                ret.append(members[name])
            else:
                logger.warning(__('missing attribute mentioned in :members: option: '
                                  'module %s, attribute %s') %
                               (safe_getattr(self.object, '__name__', '???'), name),
                               type='autodoc')
        return False, ret

def resolve_name(self, modname: str, parents: Any, path: str, base: Any
                 ) -> Tuple[str, List[str]]:
    if modname is not None:
        logger.warning(__('"::" in automodule name doesn\'t make sense'),
                       type='autodoc')
    return (path or '') + base, []

def _parse_numpydoc_see_also_section(self, content: List[str]) -> List[str]:
    """
    Derived from the NumpyDoc implementation of _parse_see_also.

    See Also
    --------
    func_name : Descriptive text
        continued text
    another_func_name : Descriptive text
    func_name1, func_name2, :meth:`func_name`, func_name3

    """
    items = []

    def parse_item_name(text: str) -> Tuple[str, str]:
        """Match ':role:`name`' or 'name'"""
        m = self._name_rgx.match(text)
        if m:
            g = m.groups()
            if g[1] is None:
                return g[3], None
            else:
                return g[2], g[1]
        raise ValueError("%s is not a item name" % text)

    def push_item(name: str, rest: List[str]) -> None:
        if not name:
            return
        name, role = parse_item_name(name)
        items.append((name, list(rest), role))
        del rest[:]

    def translate(func, description, role):
        translations = self._config.napoleon_type_aliases
        if role is not None or not translations:
            return func, description, role

        translated = translations.get(func, func)
        match = self._name_rgx.match(translated)
        if not match:
            return translated, description, role

        groups = match.groupdict()
        role = groups["role"]
        new_func = groups["name"] or groups["name2"]

        return new_func, description, role

    current_func = None
    rest = []  # type: List[str]

    for line in content:
        if not line.strip():
            continue

        m = self._name_rgx.match(line)
        if m and line[m.end():].strip().startswith(':'):
            push_item(current_func, rest)
            current_func, line = line[:m.end()], line[m.end():]
            rest = [line.split(':', 1)[1].strip()]
            if not rest[0]:
                rest = []
        elif not line.startswith(' '):
            push_item(current_func, rest)
            current_func = None
            if ',' in line:
                for func in line.split(','):
                    if func.strip():
                        push_item(func, [])
            elif line.strip():
                current_func = line
        elif current_func is not None:
            rest.append(line.strip())
    push_item(current_func, rest)

    if not items:
        return []

    # apply type aliases
    items = [
        translate(func, description, role)
        for func, description, role in items
    ]

    lines = []  # type: List[str]
    last_had_desc = True
    for name, desc, role in items:
        if role:
            link = ':%s:`%s`' % (role, name)
        else:
            link = ':obj:`%s`' % name
        if desc or last_had_desc:
            lines += ['']
            lines += [link]
        else:
            lines[-1] += ", %s" % link
        if desc:
            lines += self._indent([' '.join(desc)])
            last_had_desc = True
        else:
            last_had_desc = False
    lines += ['']

    return self._format_admonition('seealso', lines)

def _parse_see_also_section(self, section: str) -> List[str]:
    lines = self._consume_to_next_section()
    try:
        return self._parse_numpydoc_see_also_section(lines)
    except ValueError:
        return self._format_admonition('seealso', lines)

def _consume_section_header(self) -> str:
    section = next(self._line_iter)
    if not _directive_regex.match(section):
        # Consume the header underline
        next(self._line_iter)
    return section

def document_members(self, all_members: bool = False) -> None:
    if self.doc_as_attr:
        return
    super().document_members(all_members)

def can_document_member(cls, member: Any, membername: str, isattr: bool, parent: Any
                        ) -> bool:
    if inspect.isattributedescriptor(member):
        return True
    elif (not isinstance(parent, ModuleDocumenter) and
          not inspect.isroutine(member) and
          not isinstance(member, type)):
        return True
    else:
        return False

def update_annotations(self, parent: Any) -> None:
    """Update __annotations__ to support type_comment and so on."""
    try:
        annotations = dict(inspect.getannotations(parent))
        parent.__annotations__ = annotations

        for cls in inspect.getmro(parent):
            try:
                module = safe_getattr(cls, '__module__')
                qualname = safe_getattr(cls, '__qualname__')

                analyzer = ModuleAnalyzer.for_module(module)
                analyzer.analyze()
                for (classname, attrname), annotation in analyzer.annotations.items():
                    if classname == qualname and attrname not in annotations:
                        annotations[attrname] = annotation
            except (AttributeError, PycodeError):
                pass
    except TypeError:
        # Failed to set __annotations__ (built-in, extensions, etc.)
        pass

def get_class_members(subject: Any, objpath: List[str], attrgetter: Callable
                      ) -> Dict[str, "ObjectMember"]:
    """Get members and attributes of target class."""
    from sphinx.ext.autodoc import INSTANCEATTR, ObjectMember

    # the members directly defined in the class
    obj_dict = attrgetter(subject, '__dict__', {})

    members = {}  # type: Dict[str, ObjectMember]

    # enum members
    if isenumclass(subject):
        for name, value in subject.__members__.items():
            if name not in members:
                members[name] = ObjectMember(name, value, class_=subject)

        superclass = subject.__mro__[1]
        for name in obj_dict:
            if name not in superclass.__dict__:
                value = safe_getattr(subject, name)
                members[name] = ObjectMember(name, value, class_=subject)

    # members in __slots__
    try:
        __slots__ = getslots(subject)
        if __slots__:
            from sphinx.ext.autodoc import SLOTSATTR

            for name, docstring in __slots__.items():
                members[name] = ObjectMember(name, SLOTSATTR, class_=subject,
                                             docstring=docstring)
    except (TypeError, ValueError):
        pass

    # other members
    for name in dir(subject):
        try:
            value = attrgetter(subject, name)
            if ismock(value):
                value = undecorate(value)

            unmangled = unmangle(subject, name)
            if unmangled and unmangled not in members:
                if name in obj_dict:
                    members[unmangled] = ObjectMember(unmangled, value, class_=subject)
                else:
                    members[unmangled] = ObjectMember(unmangled, value)
        except AttributeError:
            continue

    try:
        for cls in getmro(subject):
            # annotation only member (ex. attr: int)
            for name in getannotations(cls):
                name = unmangle(cls, name)
                if name and name not in members:
                    members[name] = ObjectMember(name, INSTANCEATTR, class_=cls)

            # append instance attributes (cf. self.attr1) if analyzer knows
            try:
                modname = safe_getattr(cls, '__module__')
                qualname = safe_getattr(cls, '__qualname__')
                analyzer = ModuleAnalyzer.for_module(modname)
                analyzer.analyze()
                for (ns, name), docstring in analyzer.attr_docs.items():
                    if ns == qualname and name not in members:
                        members[name] = ObjectMember(name, INSTANCEATTR, class_=cls,
                                                     docstring='\n'.join(docstring))
            except (AttributeError, PycodeError):
                pass
    except AttributeError:
        pass

    return members

def _getannotations(obj: Any) -> Mapping[str, Any]:
    warnings.warn('sphinx.ext.autodoc.importer._getannotations() is deprecated.',
                  RemovedInSphinx40Warning)
    return getannotations(obj)

def get_object_members(self, want_all: bool) -> Tuple[bool, ObjectMembers]:
    members = get_class_members(self.object, self.objpath, self.get_attr)
    if not want_all:
        if not self.options.members:
            return False, []  # type: ignore
        # specific members given
        selected = []
        for name in self.options.members:  # type: str
            if name in members:
                selected.append(members[name])
            else:
                logger.warning(__('missing attribute %s in object %s') %
                               (name, self.fullname), type='autodoc')
        return False, selected
    elif self.options.inherited_members:
        return False, list(members.values())
    else:
        return False, [m for m in members.values() if m.class_ == self.object]

def is_filtered_inherited_member(name: str, obj: Any) -> bool:
    if inspect.isclass(self.object):
        for cls in self.object.__mro__:
            if cls.__name__ == self.options.inherited_members and cls != self.object:
                # given member is a member of specified *super class*
                return True
            elif name in cls.__dict__:
                return False
            elif name in self.get_attr(cls, '__annotations__', {}):
                return False
            elif isinstance(obj, ObjectMember) and obj.class_ is cls:
                return False

    return False

def annotation_option(arg: Any) -> Any:
    if arg in (None, True):
        # suppress showing the representation of the object
        return SUPPRESS
    else:
        return arg

def inherited_members_option(arg: Any) -> Union[object, Set[str]]:
    """Used to convert the :members: option to auto directives."""
    if arg in (None, True):
        return 'object'
    else:
        return arg

def _print_Function(self, expr):
    if expr.func.__name__ in self.known_functions:
        cond_func = self.known_functions[expr.func.__name__]
        func = None
        if isinstance(cond_func, str):
            func = cond_func
        else:
            for cond, func in cond_func:
                if cond(*expr.args):
                    break
        if func is not None:
            return "%s(%s)" % (func, self.stringify(expr.args, ", "))
    elif hasattr(expr, '_imp_') and isinstance(expr._imp_, Lambda):
        # inlined function
        return self._print(expr._imp_(*expr.args))
    else:
        return self._print_not_supported(expr)

def _print_not_supported(self, expr):
    self._not_supported.add(expr)
    return self.emptyPrinter(expr)

def _print(self, expr, *args, **kwargs):
    """Internal dispatcher

    Tries the following concepts to print an expression:
        1. Let the object print itself if it knows how.
        2. Take the best fitting method defined in the printer.
        3. As fall-back use the emptyPrinter method for the printer.
    """
    self._print_level += 1
    try:
        # If the printer defines a name for a printing method
        # (Printer.printmethod) and the object knows for itself how it
        # should be printed, use that method.
        if (self.printmethod and hasattr(expr, self.printmethod)
                and not isinstance(expr, BasicMeta)):
            return getattr(expr, self.printmethod)(self, *args, **kwargs)

        # See if the class of expr is known, or if one of its super
        # classes is known, and use that print function
        for cls in type(expr).__mro__:
            printmethod = '_print_' + cls.__name__
            if hasattr(self, printmethod):
                return getattr(self, printmethod)(expr, *args, **kwargs)

        # Unknown object, fall back to the emptyPrinter.
        return self.emptyPrinter(expr)
    finally:
        self._print_level -= 1

def exptrigsimp(expr):
    """
    Simplifies exponential / trigonometric / hyperbolic functions.

    Examples
    ========

    >>> from sympy import exptrigsimp, exp, cosh, sinh
    >>> from sympy.abc import z

    >>> exptrigsimp(exp(z) + exp(-z))
    2*cosh(z)
    >>> exptrigsimp(cosh(z) - sinh(z))
    exp(-z)
    """
    from sympy.simplify.fu import hyper_as_trig, TR2i
    from sympy.simplify.simplify import bottom_up

    def exp_trig(e):
        # select the better of e, and e rewritten in terms of exp or trig
        # functions
        choices = [e]
        if e.has(*_trigs):
            choices.append(e.rewrite(exp))
        choices.append(e.rewrite(cos))
        return min(*choices, key=count_ops)
    newexpr = bottom_up(expr, exp_trig)

    def f(rv):
        if not rv.is_Mul:
            return rv
        rvd = rv.as_powers_dict()
        newd = rvd.copy()

        def signlog(expr, sign=1):
            if expr is S.Exp1:
                return sign, 1
            elif isinstance(expr, exp):
                return sign, expr.args[0]
            elif sign == 1:
                return signlog(-expr, sign=-1)
            else:
                return None, None

        ee = rvd[S.Exp1]
        for k in rvd:
            if k.is_Add and len(k.args) == 2:
                # k == c*(1 + sign*E**x)
                c = k.args[0]
                sign, x = signlog(k.args[1]/c)
                if not x:
                    continue
                m = rvd[k]
                newd[k] -= m
                if ee == -x*m/2:
                    # sinh and cosh
                    newd[S.Exp1] -= ee
                    ee = 0
                    if sign == 1:
                        newd[2*c*cosh(x/2)] += m
                    else:
                        newd[-2*c*sinh(x/2)] += m
                elif newd[1 - sign*S.Exp1**x] == -m:
                    # tanh
                    del newd[1 - sign*S.Exp1**x]
                    if sign == 1:
                        newd[-c/tanh(x/2)] += m
                    else:
                        newd[-c*tanh(x/2)] += m
                else:
                    newd[1 + sign*S.Exp1**x] += m
                    newd[c] += m

        return Mul(*[k**newd[k] for k in newd])
    newexpr = bottom_up(newexpr, f)

    # sin/cos and sinh/cosh ratios to tan and tanh, respectively
    if newexpr.has(HyperbolicFunction):
        e, f = hyper_as_trig(newexpr)
        newexpr = f(TR2i(e))
    if newexpr.has(TrigonometricFunction):
        newexpr = TR2i(newexpr)

    # can we ever generate an I where there was none previously?
    if not (newexpr.has(I) and not expr.has(I)):
        expr = newexpr
    return expr

def _trigsimp(expr, deep=False):
    # protect the cache from non-trig patterns; we only allow
    # trig patterns to enter the cache
    if expr.has(*_trigs):
        return __trigsimp(expr, deep)
    return expr

def __trigsimp(expr, deep=False):
    """recursive helper for trigsimp"""
    from sympy.simplify.fu import TR10i

    if _trigpat is None:
        _trigpats()
    a, b, c, d, matchers_division, matchers_add, \
    matchers_identity, artifacts = _trigpat

    if expr.is_Mul:
        # do some simplifications like sin/cos -> tan:
        if not expr.is_commutative:
            com, nc = expr.args_cnc()
            expr = _trigsimp(Mul._from_args(com), deep)*Mul._from_args(nc)
        else:
            for i, (pattern, simp, ok1, ok2) in enumerate(matchers_division):
                if not _dotrig(expr, pattern):
                    continue

                newexpr = _match_div_rewrite(expr, i)
                if newexpr is not None:
                    if newexpr != expr:
                        expr = newexpr
                        break
                    else:
                        continue

                # use SymPy matching instead
                res = expr.match(pattern)
                if res and res.get(c, 0):
                    if not res[c].is_integer:
                        ok = ok1.subs(res)
                        if not ok.is_positive:
                            continue
                        ok = ok2.subs(res)
                        if not ok.is_positive:
                            continue
                    # if "a" contains any of trig or hyperbolic funcs with
                    # argument "b" then skip the simplification
                    if any(w.args[0] == res[b] for w in res[a].atoms(
                            TrigonometricFunction, HyperbolicFunction)):
                        continue
                    # simplify and finish:
                    expr = simp.subs(res)
                    break  # process below

    if expr.is_Add:
        args = []
        for term in expr.args:
            if not term.is_commutative:
                com, nc = term.args_cnc()
                nc = Mul._from_args(nc)
                term = Mul._from_args(com)
            else:
                nc = S.One
            term = _trigsimp(term, deep)
            for pattern, result in matchers_identity:
                res = term.match(pattern)
                if res is not None:
                    term = result.subs(res)
                    break
            args.append(term*nc)
        if args != expr.args:
            expr = Add(*args)
            expr = min(expr, expand(expr), key=count_ops)
        if expr.is_Add:
            for pattern, result in matchers_add:
