def sum_simplify(s):
    """Main function for Sum simplification"""
    from sympy.concrete.summations import Sum
    from sympy.core.function import expand

    terms = Add.make_args(expand(s))
    s_t = [] # Sum Terms
    o_t = [] # Other Terms

    for term in terms:
        if isinstance(term, Mul):
            other = 1
            sum_terms = []

            if not term.has(Sum):
                o_t.append(term)
                continue

            mul_terms = Mul.make_args(term)
            for mul_term in mul_terms:
                if isinstance(mul_term, Sum):
                    r = mul_term._eval_simplify()
                    sum_terms.extend(Add.make_args(r))
                else:
                    other = other * mul_term
            if len(sum_terms):
                #some simplification may have happened
                #use if so
                s_t.append(Mul(*sum_terms) * other)
            else:
                o_t.append(other)
        elif isinstance(term, Sum):
            #as above, we need to turn this into an add list
            r = term._eval_simplify()
            s_t.extend(Add.make_args(r))
        else:
            o_t.append(term)


    result = Add(sum_combine(s_t), *o_t)

    return result

def product_simplify(s):
    """Main function for Product simplification"""
    from sympy.concrete.products import Product

    terms = Mul.make_args(s)
    p_t = [] # Product Terms
    o_t = [] # Other Terms

    for term in terms:
        if isinstance(term, Product):
            p_t.append(term)
        else:
            o_t.append(term)

    used = [False] * len(p_t)

    for method in range(2):
        for i, p_term1 in enumerate(p_t):
            if not used[i]:
                for j, p_term2 in enumerate(p_t):
                    if not used[j] and i != j:
                        if isinstance(product_mul(p_term1, p_term2, method), Product):
                            p_t[i] = product_mul(p_term1, p_term2, method)
                            used[j] = True

    result = Mul(*o_t)

    for i, p_term in enumerate(p_t):
        if not used[i]:
            result = Mul(result, p_term)

    return result

def compute_leading_term(self, x, logx=None):
    """
    as_leading_term is only allowed for results of .series()
    This is a wrapper to compute a series first.
    """
    from sympy import Dummy, log
    from sympy.series.gruntz import calculate_series

    if self.removeO() == 0:
        return self

    if logx is None:
        d = Dummy('logx')
        s = calculate_series(self, x, d).subs(d, log(x))
    else:
        s = calculate_series(self, x, logx)

    return s.as_leading_term(x)

def doit(self, **hints):
    """Evaluates limit"""
    from sympy.series.limitseq import limit_seq
    from sympy.functions import RisingFactorial

    e, z, z0, dir = self.args

    if hints.get('deep', True):
        e = e.doit(**hints)
        z = z.doit(**hints)
        z0 = z0.doit(**hints)

    if e == z:
        return z0

    if not e.has(z):
        return e

    # gruntz fails on factorials but works with the gamma function
    # If no factorial term is present, e should remain unchanged.
    # factorial is defined to be zero for negative inputs (which
    # differs from gamma) so only rewrite for positive z0.
    if z0.is_positive:
        e = e.rewrite([factorial, RisingFactorial], gamma)

    if e.is_Mul:
        if abs(z0) is S.Infinity:
            e = factor_terms(e)
            e = e.rewrite(fibonacci, GoldenRatio)
            ok = lambda w: (z in w.free_symbols and
                            any(a.is_polynomial(z) or
                                any(z in m.free_symbols and m.is_polynomial(z)
                                    for m in Mul.make_args(a))
                                for a in Add.make_args(w)))
            if all(ok(w) for w in e.as_numer_denom()):
                u = Dummy(positive=True)
                if z0 is S.NegativeInfinity:
                    inve = e.subs(z, -1/u)
                else:
                    inve = e.subs(z, 1/u)
                r = limit(inve.as_leading_term(u), u, S.Zero, "+")
                if isinstance(r, Limit):
                    return self
                else:
                    return r

    if e.is_Order:
        return Order(limit(e.expr, z, z0), *e.args[1:])

    try:
        r = gruntz(e, z, z0, dir)
        if r is S.NaN:
            raise PoleError()
    except (PoleError, ValueError):
        r = heuristics(e, z, z0, dir)
        if r is None:
            return self
    except NotImplementedError:
        # Trying finding limits of sequences
        if hints.get('sequence', True) and z0 is S.Infinity:
            trials = hints.get('trials', 5)
            r = limit_seq(e, z, trials)
            if r is None:
                raise NotImplementedError()
        else:
            raise NotImplementedError()

    return r

def _eval_rewrite_as_Sum(self, n, k_sym=None, symbols=None):
    from sympy import Sum
    if (k_sym is not None) or (symbols is not None):
        return self

    # Dobinski's formula
    if not n.is_nonnegative:
        return self
    k = Dummy('k', integer=True, nonnegative=True)
    return 1 / E * Sum(k**n / factorial(k), (k, 0, S.Infinity))

def _bell_poly(n, prev):
    s = 1
    a = 1
    for k in range(2, n + 1):
        a = a * (n - k + 1) // (k - 1)
        s += a * prev[k - 1]
    return expand_mul(_sym * s)

def _bell_incomplete_poly(n, k, symbols):
    r"""
    The second kind of Bell polynomials (incomplete Bell polynomials).

    Calculated by recurrence formula:

    .. math:: B_{n,k}(x_1, x_2, \dotsc, x_{n-k+1}) =
            \sum_{m=1}^{n-k+1}
            \x_m \binom{n-1}{m-1} B_{n-m,k-1}(x_1, x_2, \dotsc, x_{n-m-k})

    where
        B_{0,0} = 1;
        B_{n,0} = 0; for n>=1
        B_{0,k} = 0; for k>=1

    """
    if (n == 0) and (k == 0):
        return S.One
    elif (n == 0) or (k == 0):
        return S.Zero
    s = S.Zero
    a = S.One
    for m in range(1, n - k + 2):
        s += a * bell._bell_incomplete_poly(
            n - m, k - 1, symbols) * symbols[m - 1]
        a = a * (n - m) / m
    return expand_mul(s)

def _eval_col_insert(self, pos, other):
    cols = self.cols

    def entry(i, j):
        if j < pos:
            return self[i, j]
        elif pos <= j < pos + other.cols:
            return other[i, j - pos]
        return self[i, j - pos - other.cols]

    return self._new(self.rows, self.cols + other.cols,
                     lambda i, j: entry(i, j))

def _eval_extract(self, rowsList, colsList):
    mat = self._mat
    cols = self.cols
    indices = (i * cols + j for i in rowsList for j in colsList)
    return self._new(len(rowsList), len(colsList),
                     list(mat[i] for i in indices), copy=False)

def _eval_col_insert(self, icol, other):
    if not isinstance(other, SparseMatrix):
        other = SparseMatrix(other)
    new_smat = {}
    # make room for the new rows
    for key, val in self._smat.items():
        row, col = key
        if col >= icol:
            col += other.cols
        new_smat[(row, col)] = val
    # add other's keys
    for key, val in other._smat.items():
        row, col = key
        new_smat[(row, col + icol)] = val
    return self._new(self.rows, self.cols + other.cols, new_smat)

def _eval_power(self, other):
    from sympy import Abs, arg, exp, floor, im, log, re, sign
    b, e = self.as_base_exp()
    if b is S.NaN:
        return (b**e)**other  # let __new__ handle it

    s = None
    if other.is_integer:
        s = 1
    elif b.is_polar:  # e.g. exp_polar, besselj, var('p', polar=True)...
        s = 1
    elif e.is_real is not None:
        # helper functions ===========================
        def _half(e):
            """Return True if the exponent has a literal 2 as the
            denominator, else None."""
            if getattr(e, 'q', None) == 2:
                return True
            n, d = e.as_numer_denom()
            if n.is_integer and d == 2:
                return True
        def _n2(e):
            """Return ``e`` evaluated to a Number with 2 significant
            digits, else None."""
            try:
                rv = e.evalf(2, strict=True)
                if rv.is_Number:
                    return rv
            except PrecisionExhausted:
                pass
        # ===================================================
        if e.is_real:
            # we need _half(other) with constant floor or
            # floor(S.Half - e*arg(b)/2/pi) == 0

            # handle -1 as special case
            if e == -1:
                # floor arg. is 1/2 + arg(b)/2/pi
                if _half(other):
                    if b.is_negative is True:
                        return S.NegativeOne**other*Pow(-b, e*other)
                    if b.is_real is False:
                        return Pow(b.conjugate()/Abs(b)**2, other)
            elif e.is_even:
                if b.is_real:
                    b = abs(b)
                if b.is_imaginary:
                    b = abs(im(b))*S.ImaginaryUnit

            if (abs(e) < 1) == True or e == 1:
                s = 1  # floor = 0
            elif b.is_nonnegative:
                s = 1  # floor = 0
            elif re(b).is_nonnegative and (abs(e) < 2) == True:
                s = 1  # floor = 0
            elif fuzzy_not(im(b).is_zero) and abs(e) == 2:
                s = 1  # floor = 0
            elif _half(other):
                s = exp(2*S.Pi*S.ImaginaryUnit*other*floor(
                    S.Half - e*arg(b)/(2*S.Pi)))
                if s.is_real and _n2(sign(s) - s) == 0:
                    s = sign(s)
                else:
                    s = None
        else:
            # e.is_real is False requires:
            #     _half(other) with constant floor or
            #     floor(S.Half - im(e*log(b))/2/pi) == 0
            try:
                s = exp(2*S.ImaginaryUnit*S.Pi*other*
                    floor(S.Half - im(e*log(b))/2/S.Pi))
                # be careful to test that s is -1 or 1 b/c sign(I) == I:
                # so check that s is real
                if s.is_real and _n2(sign(s) - s) == 0:
                    s = sign(s)
                else:
                    s = None
            except PrecisionExhausted:
                s = None

    if s is not None:
        return s*Pow(b, e*other)

def _eval_rewrite(self, pattern, rule, **hints):
    if self.is_Atom:
        if hasattr(self, rule):
            return getattr(self, rule)()
        return self

    if hints.get('deep', True):
        args = [a._eval_rewrite(pattern, rule, **hints)
                    if isinstance(a, Basic) else a
                    for a in self.args]
    else:
        args = self.args

    if pattern is None or isinstance(self, pattern):
        if hasattr(self, rule):
            rewritten = getattr(self, rule)(*args)
            if rewritten is not None:
                return rewritten
    return self.func(*args)

